import { useEffect, useRef, useState } from 'react';
import type { RecordedStep, NetworkRequestSummary, ConsoleMessageSummary, TestFinding } from '../../../../activator/types/state';
import type { ServerMessage } from '../../../../activator/types/protocol';
import { useActivator } from '../../../store/Context';
import { executionStepScreenshotUrl } from '../../../store/activatorApi';
import NetworkRequestCard from '../../../components/network/NetworkRequestCard';
import ConsoleMessageCard from '../../../components/network/ConsoleMessageCard';
import ToolDataPreview from '../../../components/ToolDataPreview';

interface StepDetailModalProps {
  step: RecordedStep;
  findings?: TestFinding[];
  /**
   * When supplied, the modal lazy-loads per-step network/console payload
   * from disk (history runs) and serves the screenshot via the REST URL
   * tied to that run. Live in-memory steps from the running test case
   * pass `runContext: undefined` and use the inline base64 screenshot +
   * inline log arrays.
   */
  runContext?: { runId: string; testCaseId: string };
  onClose: () => void;
}

type TabId = 'details' | 'network' | 'console' | 'screenshot';

export default function StepDetailModal({ step, findings = [], runContext, onClose }: StepDetailModalProps) {
  const stepFindings = findings.filter((f) => f.stepId === step.id);
  const [activeTab, setActiveTab] = useState<TabId>('details');
  const [logs, setLogs] = useState<{ networkRequests?: NetworkRequestSummary[]; consoleMessages?: ConsoleMessageSummary[] } | null>(null);
  const requestIdRef = useRef<string | null>(null);
  const proxy = useActivator();

  useEffect(() => {
    if (!runContext || !proxy) return;
    const inMemoryEmpty =
      (!step.networkRequests || step.networkRequests.length === 0) &&
      (!step.consoleMessages || step.consoleMessages.length === 0);
    if (!inMemoryEmpty) return;

    const rid = `step_logs_${step.id}_${Date.now()}`;
    requestIdRef.current = rid;

    const unsubscribe = proxy.subscribe((msg: ServerMessage) => {
      if (msg.type === 'stepLogsLoaded' && msg.data.requestId === rid) {
        setLogs({ networkRequests: msg.data.networkRequests, consoleMessages: msg.data.consoleMessages });
      }
    });

    proxy.loadStepLogs(runContext.runId, runContext.testCaseId, step.id, rid);
    return () => unsubscribe();
  }, [runContext, proxy, step.id, step.networkRequests, step.consoleMessages]);

  const networkRequests = logs?.networkRequests ?? step.networkRequests ?? [];
  const consoleMessages = logs?.consoleMessages ?? step.consoleMessages ?? [];

  const screenshotInline = step.screenshotAfter;
  const screenshotUrl = !screenshotInline && runContext && step.screenshotAfterFile
    ? executionStepScreenshotUrl(runContext.runId, runContext.testCaseId, step.id, 'after')
    : undefined;

  const handleBackdropClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget) onClose();
  };

  const errorCount = consoleMessages.filter((m) => m.type === 'error').length;
  const networkErrorCount = networkRequests.filter((r) => r.failed || (r.status ?? 0) >= 400).length;

  const hasScreenshot = Boolean(screenshotInline || screenshotUrl);

  const tabs: { id: TabId; label: string; count?: number; tone?: 'red' }[] = [
    { id: 'details', label: 'Details', count: stepFindings.length || undefined },
    ...(networkRequests.length > 0
      ? [{ id: 'network' as const, label: 'Network', count: networkRequests.length, tone: networkErrorCount > 0 ? ('red' as const) : undefined }]
      : []),
    ...(consoleMessages.length > 0
      ? [{ id: 'console' as const, label: 'Console', count: consoleMessages.length, tone: errorCount > 0 ? ('red' as const) : undefined }]
      : []),
    ...(hasScreenshot ? [{ id: 'screenshot' as const, label: 'Screenshot' }] : []),
  ];

  const visibleTabIds = tabs.map((t) => t.id).join(',');
  useEffect(() => {
    if (!visibleTabIds.split(',').includes(activeTab)) setActiveTab('details');
  }, [visibleTabIds, activeTab]);

  return (
    <div className="fixed inset-0 bg-[rgba(0,0,0,0.5)] flex items-end z-50" onClick={handleBackdropClick}>
      <div className="bg-white rounded-t-2xl shadow-xl w-full min-h-[65vh] max-h-[65vh] animate-slide-up overflow-hidden flex flex-col">
        <div className="sticky top-0 bg-white border-b border-gray-200 px-4 py-3 shrink-0">
          <div className="w-12 h-1 bg-gray-300 rounded-full mx-auto mb-2" />
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className={`w-2.5 h-2.5 rounded-full ${step.result.success ? 'bg-green-500' : 'bg-red-500'}`} />
              <h2 className="text-sm font-semibold text-gray-800">
                Step {step.index + 1}: {step.toolName}
              </h2>
              <span className="text-xs text-gray-400">{step.result.duration}ms</span>
            </div>
            <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1 cursor-pointer">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          <div className="flex gap-1 mt-2">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors cursor-pointer ${
                  activeTab === tab.id ? 'bg-[#1e2939] text-white' : 'text-gray-500 hover:bg-gray-100'
                }`}
              >
                {tab.label}
                {tab.count != null && tab.count > 0 && (
                  <span
                    className={`ml-1 px-1.5 py-0.5 rounded-full text-[10px] ${
                      activeTab === tab.id
                        ? 'bg-white/20'
                        : tab.tone === 'red'
                          ? 'bg-red-100 text-red-700'
                          : 'bg-gray-200'
                    }`}
                  >
                    {tab.count}
                  </span>
                )}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4">
          {activeTab === 'details' && (
            <div className="space-y-4">
              {stepFindings.length > 0 && (
                <div>
                  <h3 className="text-xs font-semibold text-gray-500 uppercase mb-1">Findings</h3>
                  <div className="space-y-1.5">
                    {stepFindings.map((f) => {
                      const styles =
                        f.type === 'fail' ? { bg: 'bg-red-50', border: 'border-red-200', text: 'text-red-700', icon: '✗' } :
                        f.type === 'pass' ? { bg: 'bg-green-50', border: 'border-green-200', text: 'text-green-700', icon: '✓' } :
                        f.type === 'warning' ? { bg: 'bg-yellow-50', border: 'border-yellow-200', text: 'text-yellow-700', icon: '!' } :
                        { bg: 'bg-gray-50', border: 'border-gray-200', text: 'text-gray-600', icon: 'i' };
                      return (
                        <div key={f.id} className={`rounded-lg border p-3 flex items-start gap-2 ${styles.bg} ${styles.border}`}>
                          <span className={`shrink-0 font-bold text-sm ${styles.text}`}>{styles.icon}</span>
                          <p className={`text-xs wrap-break-word flex-1 ${styles.text}`}>{f.message}</p>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}

              {step.aiReasoning && (
                <div>
                  <h3 className="text-xs font-semibold text-gray-500 uppercase mb-1">AI Reasoning</h3>
                  <p className="text-sm text-gray-700 bg-blue-50 rounded-lg p-3 border border-blue-100">
                    {step.aiReasoning}
                  </p>
                </div>
              )}

              <div>
                <h3 className="text-xs font-semibold text-gray-500 uppercase mb-1">Arguments</h3>
                <div className="bg-gray-50 rounded-lg p-3 border border-gray-200">
                  <ToolDataPreview
                    value={step.toolArgs}
                    className="text-xs text-gray-700 font-mono whitespace-pre-wrap break-all"
                    imageAlt={`${step.toolName} argument image`}
                  />
                </div>
              </div>

              <div>
                <h3 className="text-xs font-semibold text-gray-500 uppercase mb-1">Result</h3>
                <div className={`rounded-lg p-3 border text-sm ${
                  step.result.success ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'
                }`}>
                  <span className={`font-semibold ${step.result.success ? 'text-green-700' : 'text-red-700'}`}>
                    {step.result.success ? 'Success' : 'Failed'}
                  </span>
                  {step.result.error && <p className="text-red-600 text-xs mt-1">{step.result.error}</p>}
                  {step.result.data != null && (
                    <div className="mt-2">
                      <ToolDataPreview value={step.result.data} imageAlt={`${step.toolName} result image`} />
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'network' && (
            <div className="space-y-1">
              {networkRequests.map((req, i) => <NetworkRequestCard key={i} req={req} />)}
            </div>
          )}

          {activeTab === 'console' && (
            <div className="space-y-0.5">
              {consoleMessages.map((msg, i) => <ConsoleMessageCard key={i} msg={msg} />)}
            </div>
          )}

          {activeTab === 'screenshot' && (screenshotInline || screenshotUrl) && (
            <div>
              <img
                src={screenshotInline ? `data:image/png;base64,${screenshotInline}` : screenshotUrl}
                alt="After step"
                className="w-full rounded-lg border border-gray-200"
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
