// Single flat catalog of every selectable LLM model across providers.
// Filter by `provider` to get the list for a given provider. Capability flags
// drive task-aware filtering in the model picker; tags are free-form labels
// (cloud / local / experimental / legacy / code / heavy / default / reasoning).

export type ModelProvider = 'openai' | 'bedrock' | 'bedrockapi' | 'gh-copilot' | 'claudecode' | 'ollama';

export type ModelCapability = 'vision' | 'tools' | 'json' | 'longContext' | 'reasoning';

export interface ModelInfo {
    id: string;
    provider: ModelProvider;
    name?: string;
    description: string;
    capabilities: ModelCapability[];
    tags?: string[];
}

export type TaskKey =
    | 'vision'
    | 'testCaseGeneration'
    | 'testPlanGeneration'
    | 'featureClassification'
    | 'stepExecution'
    | 'comparison'
    | 'codeGeneration'
    | 'documentation'
    | 'summaryReportGeneration'
    | 'defectDrafting';

// What each task needs from a model.
// `required`: HARD requirement — model is blocked from selection if missing.
// `recommended`: SOFT requirement — selection allowed but the picker shows
//   a warning so the user understands the tradeoff.
//
// Sourced from real call-site analysis:
//   stepExecution    → uses tool calling (SessionExecutor), sends screenshots.
//   comparison       → sends two base64 images and uses tools.
//   vision task      → image-only.
//   *Generation/json tasks rely on parseable JSON; mostly recoverable from
//   text, so they're recommended rather than required.
export interface TaskRequirements {
    required: ModelCapability[];
    recommended: ModelCapability[];
}

export const TASK_REQUIREMENTS: Record<TaskKey, TaskRequirements> = {
    vision: {
        required: ['vision'],
        recommended: [],
    },
    testCaseGeneration: {
        required: [],
        recommended: ['longContext'],
    },
    testPlanGeneration: {
        required: [],
        recommended: ['json', 'longContext'],
    },
    featureClassification: {
        required: [],
        recommended: ['json'],
    },
    stepExecution: {
        // Tool calling is mandatory — the executor drives the browser via the
        // model's tool_use turns. Without it, the agentic loop cannot run.
        required: ['tools'],
        // Vision is the primary signal; text-only models work poorly because
        // the executor's main observation is a screenshot.
        recommended: ['vision'],
    },
    comparison: {
        // Both sides are required: the engine renders pairs of images and
        // expects tool-driven feedback iterations.
        required: ['vision', 'tools'],
        recommended: ['json', 'longContext'],
    },
    codeGeneration: {
        required: [],
        recommended: ['longContext'],
    },
    documentation: {
        required: [],
        recommended: [],
    },
    summaryReportGeneration: {
        required: [],
        recommended: ['longContext'],
    },
    defectDrafting: {
        required: [],
        recommended: ['json'],
    },
};

