export function modelInfosFor(provider: string): ModelInfo[] {
    return MODEL_CATALOG.filter((m) => m.provider === provider);
}

// Backwards-compatible helper. Returns plain ID strings for callers that
// only need a flat list.
export function modelsFor(provider: string): string[] {
    return modelInfosFor(provider).map((m) => m.id);
}

export function missingCapabilities(m: ModelInfo, caps: ModelCapability[]): ModelCapability[] {
    return caps.filter((cap) => !m.capabilities.includes(cap));
}

export interface ModelEvaluation {
    /** Hard-blocked: the model is missing required capabilities. */
    blocked: boolean;
    missingRequired: ModelCapability[];
    /** Allowed but suboptimal: missing recommended capabilities. */
    missingRecommended: ModelCapability[];
}

export function evaluateModelForTask(m: ModelInfo, taskKey: TaskKey): ModelEvaluation {
    const req = TASK_REQUIREMENTS[taskKey];
    const missingRequired = missingCapabilities(m, req.required);
    const missingRecommended = missingCapabilities(m, req.recommended);
    return {
        blocked: missingRequired.length > 0,
        missingRequired,
        missingRecommended,
    };
}
