import { useNavigate, useParams } from 'react-router-dom';
import { useActivator } from '../../store/Context';
import { useStore } from '../../store/state';
import RunCard from './RunCard';

export default function ExecutionHistoryList() {
    const { projectId, moduleId, featureId } = useParams<{
        projectId: string;
        moduleId: string;
        featureId: string;
    }>();
    const navigate = useNavigate();
    const activator = useActivator();
    const setDefectDraft = useStore((s) => s.setDefectDraft);

    const project = useStore((s) => s.projects.find((p) => p.id === projectId));
    const mod = project?.modules.find((m) => m.id === moduleId);
    const feature = mod?.features.find((f) => f.id === featureId);

    if (!project || !mod || !feature) {
        return (
            <div className="w-full px-4 py-6">
                <div className="rounded-lg border border-gray-200 bg-white p-6 text-center text-gray-500 text-sm">
                    Feature not found
                </div>
            </div>
        );
    }

    const pid = project.id;
    const mid = mod.id;
    const fid = feature.id;
    const runs = [...(feature.testRuns || [])].reverse();

    const handleOpen = (runId: string) => {
        navigate(`/project/${pid}/module/${mid}/feature/${fid}/tests?runId=${encodeURIComponent(runId)}`);
    };

    const handleDelete = (runId: string) => {
        activator.deleteTestRun(pid, mid, fid, runId);
    };

    const handleDraftBug = (runId: string, testCaseId: string) => {
        setDefectDraft({ projectId: pid, moduleId: mid, featureId: fid, runId, testCaseId, status: 'drafting' });
        activator.draftDefect(pid, mid, fid, runId, testCaseId);
    };

    return (
        <div className="w-full px-4 py-6">
            <div className="flex items-center gap-2 mb-3 text-sm flex-wrap">
                <button
                    onClick={() => navigate(`/project/${pid}/module/${mid}`)}
                    className="inline-flex items-center gap-1 px-2 py-1 text-xs text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-md transition cursor-pointer"
                    title="Back to Module"
                >
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                    </svg>
                    Back
                </button>
                <span className="text-gray-300">|</span>
                <button onClick={() => navigate('/')} className="text-gray-400 hover:text-gray-700 text-xs cursor-pointer">
                    Projects
                </button>
                <span className="text-gray-300">/</span>
                <button onClick={() => navigate(`/project/${pid}`)} className="text-gray-400 hover:text-gray-700 text-xs cursor-pointer">
                    {project.name}
                </button>
                <span className="text-gray-300">/</span>
                <button onClick={() => navigate(`/project/${pid}/module/${mid}`)} className="text-gray-400 hover:text-gray-700 text-xs cursor-pointer">
                    {mod.name}
                </button>
                <span className="text-gray-300">/</span>
                <button
                    onClick={() => navigate(`/project/${pid}/module/${mid}/feature/${fid}`)}
                    className="text-gray-400 hover:text-gray-700 text-xs cursor-pointer"
                >
                    {feature.name}
                </button>
                <span className="text-gray-300">/</span>
                <span className="font-medium text-gray-800 text-xs">History</span>
            </div>

            <div className="rounded-lg border border-gray-200 bg-white px-4 py-4">
                <h1 className="text-base font-bold text-gray-800 mb-3">Execution History — {feature.name}</h1>

                {runs.length === 0 && (
                    <p className="text-xs text-gray-500 py-6 text-center">No execution runs yet.</p>
                )}

                <div className="space-y-2">
                    {runs.map((run) => (
                        <RunCard
                            key={run.id}
                            run={run}
                            onOpen={handleOpen}
                            onDelete={handleDelete}
                            onDraftBug={handleDraftBug}
                        />
                    ))}
                </div>
            </div>
        </div>
    );
}
