import { useNavigate } from 'react-router-dom';
import type { ActivityEntry, ProjectDashboard } from '../../lib/dashboard';
import { formatRelative } from '../../lib/dashboard';

interface Props {
  projectId: string;
  activity: ActivityEntry[];
  live: ProjectDashboard['live'];
  projectName: string;
}

function RunIcon() {
  return (
    <svg className="w-3.5 h-3.5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-5.197-3.03A1 1 0 008 9v6a1 1 0 001.555.832l5.197-3.03a1 1 0 000-1.664z" />
    </svg>
  );
}

function DiffIcon() {
  return (
    <svg className="w-3.5 h-3.5 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h13M8 12h13M8 17h13M3 7h.01M3 12h.01M3 17h.01" />
    </svg>
  );
}

export default function ActivityFeed({ projectId, activity, live, projectName }: Props) {
  const navigate = useNavigate();
  const hasLive = !!(live.executionInFlight || live.comparisonInFlight);

  const comparisonTarget = (() => {
    const c = live.comparisonInFlight;
    if (!c || !c.moduleId) return null;
    return c.featureId
      ? `/project/${projectId}/module/${c.moduleId}/feature/${c.featureId}/compare`
      : `/project/${projectId}/module/${c.moduleId}/compare`;
  })();

  return (
    <div className="rounded-2xl border border-gray-200 bg-white overflow-hidden">
      <div className="px-4 py-3 border-b border-gray-200">
        <h2 className="text-sm font-semibold text-gray-800">Activity</h2>
        <p className="text-[11px] text-gray-400 mt-0.5">Recent runs and comparisons for {projectName}</p>
      </div>

      {hasLive && (
        <div className="bg-orange-50 border-b border-orange-200 px-4 py-1.5 flex items-center gap-2 flex-wrap">
          <span className="relative flex h-2 w-2 shrink-0">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-orange-500 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-2 w-2 bg-orange-600"></span>
          </span>
          <span className="text-[10px] font-semibold uppercase tracking-wide text-orange-700 shrink-0">In progress</span>
          {live.executionInFlight && (
            <span className="text-[11px] text-gray-600">Test execution running</span>
          )}
          {live.comparisonInFlight && (
            <span
              onClick={() => comparisonTarget && navigate(comparisonTarget)}
              className={`text-[11px] text-gray-600 ${comparisonTarget ? 'hover:text-orange-700 cursor-pointer underline decoration-dotted underline-offset-2' : ''}`}
              title={comparisonTarget ? 'View live comparison progress' : undefined}
            >
              Comparison running
            </span>
          )}
        </div>
      )}

      {activity.length === 0 ? (
        <div className="p-8 text-center text-xs text-gray-500">No activity yet.</div>
      ) : (
        <ul className="divide-y divide-gray-100">
          {activity.map(entry => {
            if (entry.kind === 'run') {
              return (
                <li
                  key={entry.runId}
                  onClick={() =>
                    navigate(`/project/${projectId}/module/${entry.moduleId}/feature/${entry.featureId}/history`)
                  }
                  className="p-3 hover:bg-gray-50 cursor-pointer flex items-start gap-2 min-w-0"
                >
                  <RunIcon />
                  <div className="flex-1 min-w-0">
                    <div className="text-xs font-semibold text-gray-800 truncate">
                      {entry.mode === 'replay' ? 'Replay run' : 'AI run'} — {entry.featureName}
                    </div>
                    <div className="text-[10px] text-gray-500">
                      <span className="text-green-600">{entry.passed} passed</span>
                      {entry.failed > 0 && <>, <span className="text-red-600">{entry.failed} failed</span></>}
                      {' · '}
                      {formatRelative(entry.startedAt)}
                    </div>
                  </div>
                </li>
              );
            }
            const target = entry.featureId && entry.moduleId
              ? `/project/${projectId}/module/${entry.moduleId}/feature/${entry.featureId}/compare`
              : entry.moduleId
                ? `/project/${projectId}/module/${entry.moduleId}/compare`
                : null;
            const mismatches = entry.mismatchCount ?? entry.findingsCount;
            const totalDiffs = entry.totalDiffs;
            const modeLabel = entry.useAI === false ? 'Replay' : entry.useAI === true ? 'AI' : null;
            const titlePrefix = entry.planTitle
              ? entry.planTitle
              : `Comparison — ${entry.scopeLabel}`;
            return (
              <li
                key={entry.comparisonId}
                onClick={() => {
                  if (target) navigate(target);
                }}
                className={`p-3 flex items-start gap-2 min-w-0 ${target ? 'hover:bg-gray-50 cursor-pointer' : ''}`}
              >
                <DiffIcon />
                <div className="flex-1 min-w-0">
                  <div className="text-xs font-semibold text-gray-800 truncate">
                    {titlePrefix}
                    {entry.planTitle && <span className="text-gray-400 font-normal"> — {entry.scopeLabel}</span>}
                    {modeLabel && (
                      <span className="ml-1 inline-block text-[9px] font-semibold uppercase tracking-wide text-purple-700 bg-purple-50 border border-purple-200 rounded px-1 align-middle">
                        {modeLabel}
                      </span>
                    )}
                    {entry.isReplay && (
                      <span className="ml-1 inline-block text-[9px] font-semibold uppercase tracking-wide text-gray-600 bg-gray-100 border border-gray-200 rounded px-1 align-middle">
                        ↻
                      </span>
                    )}
                  </div>
                  <div className="text-[10px] text-gray-500 truncate">
                    <span className={mismatches > 0 ? 'text-red-600 font-semibold' : 'text-green-600'}>
                      {mismatches} mismatch{mismatches === 1 ? '' : 'es'}
                    </span>
                    {typeof totalDiffs === 'number' && totalDiffs > 0 && <> / {totalDiffs} diff{totalDiffs === 1 ? '' : 's'}</>}
                    {entry.status === 'running' && <> · <span className="text-orange-600 font-semibold">running</span></>}
                    {entry.status === 'failed' && <> · <span className="text-red-600 font-semibold">failed</span></>}
                    {' · '}
                    {formatRelative(entry.startedAt)}
                  </div>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}
