import { useEffect, useRef, useState } from 'react';
import type { ComparisonStep } from '../../../activator/types/comparisonPlan';
import type { NetworkRequestSummary, ConsoleMessageSummary } from '../../../activator/types/state';
import type { ServerMessage } from '../../../activator/types/protocol';
import { useActivator } from '../../store/Context';
import { comparisonStepScreenshotUrl } from '../../store/activatorApi';
import NetworkRequestCard from '../../components/network/NetworkRequestCard';
import ConsoleMessageCard from '../../components/network/ConsoleMessageCard';
import ToolDataPreview from '../../components/ToolDataPreview';
import { getComparisonStepTitle } from './ComparisonStepRow';

interface Props {
  step: ComparisonStep;
  /**
   * When supplied, the modal lazy-loads logs (network + console) from the
   * persisted run via WebSocket and references the screenshot via the
   * REST URL. Live runs pass these too — runId is known the moment the
   * run starts; the screenshot is broadcast inline (base64) for the
   * currently-running step, so the modal prefers inline data when
   * present and falls back to the REST URL otherwise.
   */
  runContext?: { runId: string; stateId: string; testCaseId: string };
  onClose: () => void;
}

const COMMON_BADGE = 'common';

type TabId = 'details' | 'network' | 'console' | 'screenshot';

export default function ComparisonStepDetailModal({ step, runContext, onClose }: Props) {
  const title = getComparisonStepTitle(step);
  const sessionBadge = step.sessionId ?? COMMON_BADGE;
  const cleanArgs = stripBookkeepingKeys(step.toolArgs);
  const hasArgs = Object.keys(cleanArgs).length > 0;
  const resultData = unwrapResultData(step.result);

  const [activeTab, setActiveTab] = useState<TabId>('details');
  const [logs, setLogs] = useState<{ networkRequests?: NetworkRequestSummary[]; consoleMessages?: ConsoleMessageSummary[] } | null>(null);
  const requestIdRef = useRef<string | null>(null);
  const proxy = useActivator();

  useEffect(() => {
    if (!runContext || !proxy) return;
    const inMemoryEmpty =
      (!step.networkRequests || step.networkRequests.length === 0) &&
      (!step.consoleMessages || step.consoleMessages.length === 0);
    if (!inMemoryEmpty) return;

    const rid = `cstep_logs_${step.id}_${Date.now()}`;
    requestIdRef.current = rid;

    const unsubscribe = proxy.subscribe((msg: ServerMessage) => {
      if (msg.type === 'comparisonStepLogsLoaded' && msg.data.requestId === rid) {
        setLogs({ networkRequests: msg.data.networkRequests, consoleMessages: msg.data.consoleMessages });
      }
    });

    proxy.loadComparisonStepLogs(rid, runContext.runId, runContext.stateId, runContext.testCaseId, step.id);
    return () => unsubscribe();
  }, [runContext, proxy, step.id, step.networkRequests, step.consoleMessages]);

  const networkRequests = logs?.networkRequests ?? step.networkRequests ?? [];
  const consoleMessages = logs?.consoleMessages ?? step.consoleMessages ?? [];

  const screenshotInline = step.screenshotBase64;
  const screenshotUrl = !screenshotInline && runContext && step.screenshotFile
    ? comparisonStepScreenshotUrl(runContext.runId, runContext.stateId, runContext.testCaseId, step.id)
    : undefined;

  const errorCount = consoleMessages.filter((m) => m.type === 'error').length;
  const networkErrorCount = networkRequests.filter((r) => r.failed || (r.status ?? 0) >= 400).length;

  const hasScreenshot = Boolean(screenshotInline || screenshotUrl);

  const tabs: { id: TabId; label: string; count?: number; tone?: 'red' }[] = [
    { id: 'details', label: 'Details' },
    ...(networkRequests.length > 0
      ? [{ id: 'network' as const, label: 'Network', count: networkRequests.length, tone: networkErrorCount > 0 ? ('red' as const) : undefined }]
      : []),
    ...(consoleMessages.length > 0
      ? [{ id: 'console' as const, label: 'Console', count: consoleMessages.length, tone: errorCount > 0 ? ('red' as const) : undefined }]
      : []),
    ...(hasScreenshot ? [{ id: 'screenshot' as const, label: 'Screenshot' }] : []),
  ];

  const visibleTabIds = tabs.map((t) => t.id).join(',');
  useEffect(() => {
    if (!visibleTabIds.split(',').includes(activeTab)) setActiveTab('details');
  }, [visibleTabIds, activeTab]);

  const handleBackdropClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget) onClose();
  };

  return (
    <div className="fixed inset-0 bg-[rgba(0,0,0,0.5)] flex items-end z-50" onClick={handleBackdropClick}>
      <div className="bg-white rounded-t-2xl shadow-xl w-full min-h-[65vh] max-h-[80vh] animate-slide-up overflow-hidden flex flex-col">
        <div className="sticky top-0 bg-white border-b border-gray-200 px-4 py-3 shrink-0">
          <div className="w-12 h-1 bg-gray-300 rounded-full mx-auto mb-2" />
          <div className="flex items-center justify-between gap-2">
            <div className="flex items-center gap-2 min-w-0">
              <span
                className={`w-2.5 h-2.5 rounded-full shrink-0 ${
                  step.status === 'failed' ? 'bg-red-500' : step.status === 'running' ? 'bg-orange-500 animate-pulse' : 'bg-green-500'
                }`}
              />
              <h2 className="text-sm font-semibold text-gray-800 truncate">{title}</h2>
              <span className="text-xs text-gray-400 shrink-0">{step.toolName}</span>
              {typeof step.durationMs === 'number' && (
                <span className="text-xs text-gray-400 shrink-0">· {step.durationMs}ms</span>
              )}
            </div>
            <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1 cursor-pointer shrink-0">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          <div className="flex gap-1 mt-2">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors cursor-pointer ${
                  activeTab === tab.id ? 'bg-[#1e2939] text-white' : 'text-gray-500 hover:bg-gray-100'
                }`}
              >
                {tab.label}
                {tab.count != null && tab.count > 0 && (
                  <span
                    className={`ml-1 px-1.5 py-0.5 rounded-full text-[10px] ${
                      activeTab === tab.id
                        ? 'bg-white/20'
                        : tab.tone === 'red'
                          ? 'bg-red-100 text-red-700'
                          : 'bg-gray-200'
                    }`}
                  >
                    {tab.count}
                  </span>
                )}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {activeTab === 'details' && (
            <>
              <div className="flex items-center gap-2 text-xs text-gray-600">
                <span className="font-semibold text-gray-500 uppercase text-[10px]">Session</span>
                <span className="font-mono px-1.5 py-0.5 rounded bg-gray-100">{sessionBadge}</span>
              </div>

              {step.error && (
                <div>
                  <h3 className="text-xs font-semibold text-gray-500 uppercase mb-1">Error</h3>
                  <pre className="text-xs text-red-700 font-mono whitespace-pre-wrap break-all bg-red-50 rounded-lg p-3 border border-red-200">
                    {step.error}
                  </pre>
                </div>
              )}

              {hasArgs && (
                <div>
                  <h3 className="text-xs font-semibold text-gray-500 uppercase mb-1">Arguments</h3>
                  <div className="bg-gray-50 rounded-lg p-3 border border-gray-200">
                    <ToolDataPreview
                      value={cleanArgs}
                      className="text-xs text-gray-700 font-mono whitespace-pre-wrap break-all"
                      imageAlt={`${step.toolName} argument image`}
                    />
                  </div>
                </div>
              )}

              <div>
                <h3 className="text-xs font-semibold text-gray-500 uppercase mb-1">Result</h3>
                <div
                  className={`rounded-lg p-3 border text-sm ${
                    step.status === 'failed' ? 'bg-red-50 border-red-200' : 'bg-green-50 border-green-200'
                  }`}
                >
                  <span className={`font-semibold capitalize ${step.status === 'failed' ? 'text-red-700' : 'text-green-700'}`}>
                    {step.status}
                  </span>
                  {resultData !== undefined && resultData !== null && (
                    <div className="mt-2">
                      <ToolDataPreview value={resultData} imageAlt={`${step.toolName} result image`} />
                    </div>
                  )}
                </div>
              </div>
            </>
          )}

          {activeTab === 'network' && (
            <div className="space-y-1">
              {networkRequests.map((req, i) => <NetworkRequestCard key={i} req={req} />)}
            </div>
          )}

          {activeTab === 'console' && (
            <div className="space-y-0.5">
              {consoleMessages.map((msg, i) => <ConsoleMessageCard key={i} msg={msg} />)}
            </div>
          )}

          {activeTab === 'screenshot' && (screenshotInline || screenshotUrl) && (
            <div>
              <img
                src={screenshotInline ? `data:image/png;base64,${screenshotInline}` : screenshotUrl}
                alt={`${step.toolName} screenshot`}
                className="w-full rounded-lg border border-gray-200"
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function stripBookkeepingKeys(args: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(args)) {
    if (k === '__selectorFallbacks' || k === '__elementInfo') continue;
    out[k] = v;
  }
  return out;
}

function unwrapResultData(result: unknown): unknown {
  if (!result || typeof result !== 'object') return result;
  const r = result as { success?: unknown; data?: unknown; error?: unknown };
  if ('data' in r) return r.data;
  return result;
}
