import { useMemo, useState } from 'react';
import type { ComparisonRun } from '../../../activator/types/comparisonPlan';
import { useStore } from '../../store/state';
import { useActivator } from '../../store/Context';
import ComparisonDiffDetailModal from './ComparisonDiffDetailModal';

const KIND_LABELS: Record<string, string> = {
  table_diff: 'Table',
  form_diff: 'Form',
  chart_diff: 'Chart',
  section_diff: 'Section',
  style_diff: 'Style',
};

const EMPTY_LIVE_DIFFS: Record<string, never> = Object.freeze({});
const EMPTY_TEST_CASES: Record<string, never> = Object.freeze({});

const TWO_LINE_CHAR_THRESHOLD = 120;

// Label used when a diff/finding has no test case title — happens on old
// historic runs recorded before testCaseTitle was captured.
const UNGROUPED_LABEL = 'General';

// ─── data helpers ─────────────────────────────────────────────────────────────

function extractFindingsFromTestCases(testCases: ReadonlyArray<{
  title: string;
  steps?: ReadonlyArray<{ toolName: string; toolArgs: Record<string, unknown>; id?: string; startedAt?: string }>;
}>): FindingItem[] {
  const out: FindingItem[] = [];
  for (const tc of testCases) {
    for (const step of tc.steps ?? []) {
      if (step.toolName !== 'record_finding') continue;
      const args = step.toolArgs as { type?: string; title?: string; description?: string; message?: string; isBug?: boolean; __source?: string } | undefined;
      const description = typeof args?.description === 'string' ? args.description.trim() : '';
      const legacyMessage = typeof args?.message === 'string' ? args.message.trim() : '';
      const title = typeof args?.title === 'string' ? args.title.trim() : '';
      const message = description || legacyMessage || title;
      if (!message) continue;
      const rawType = args?.type;
      const type: FindingItem['type'] =
        rawType === 'fail' || rawType === 'warning' || rawType === 'info' || rawType === 'pass' ? rawType : 'info';
      out.push({
        type,
        message,
        testCaseTitle: tc.title,
        isBug: typeof args?.isBug === 'boolean' ? args.isBug : undefined,
        recordedAt: step.startedAt,
        source: args?.__source === 'replay' ? 'replay' : 'ai',
      });
    }
  }
  return out;
}

function backfillDiffTimestamps(
  diffs: ReadonlyArray<DiffItem>,
  testCases: ReadonlyArray<{ steps?: ReadonlyArray<{ toolName: string; toolArgs: Record<string, unknown>; startedAt?: string }> }>,
): DiffItem[] {
  let needsBackfill = false;
  for (const d of diffs) { if (!d.recordedAt) { needsBackfill = true; break; } }
  if (!needsBackfill) return diffs as DiffItem[];

  const tsByKey = new Map<string, string>();
  for (const tc of testCases) {
    for (const step of tc.steps ?? []) {
      if (!step.toolName.startsWith('compare_')) continue;
      const key = (step.toolArgs as { diffArtifactKey?: unknown }).diffArtifactKey;
      if (typeof key === 'string' && key && step.startedAt) tsByKey.set(key, step.startedAt);
    }
  }
  return diffs.map((d) => (d.recordedAt ? d : { ...d, recordedAt: tsByKey.get(d.artifactKey) }));
}

function mergeDiffs(persisted: ReadonlyArray<DiffItem>, live: ReadonlyArray<DiffItem>): DiffItem[] {
  const merged: DiffItem[] = [];
  const seenKeys = new Set<string>();
  for (const d of persisted) {
    const key = d.artifactKey || `${d.kind}::${d.summary}`;
    merged.push(d);
    seenKeys.add(key);
  }
  for (const d of live) {
    const key = d.artifactKey || `${d.kind}::${d.summary}`;
    if (!seenKeys.has(key)) merged.push(d);
  }
  return merged;
}

function dedupeFindings(items: FindingItem[]): FindingItem[] {
  const byKey = new Map<string, FindingItem>();
  for (const f of items) {
    const k = `${f.testCaseTitle}|${f.type}|${f.message}`;
    const existing = byKey.get(k);
    if (!existing) {
      byKey.set(k, f);
      continue;
    }
    if (!existing.recordedAt && f.recordedAt) byKey.set(k, f);
    else if (existing.recordedAt && f.recordedAt && f.recordedAt < existing.recordedAt) byKey.set(k, f);
  }
  return Array.from(byKey.values());
}

/**
 * Group a flat chronological timeline of diffs and findings by test case title.
 * Items without a title land in the UNGROUPED_LABEL group (old historic runs).
 * Within each group items stay in chronological order.
 */
function groupByTestCase(diffs: ReadonlyArray<DiffItem>, findings: ReadonlyArray<FindingItem>): TestCaseGroup[] {
  // Merge into one timeline first so chronological order within each group
  // is preserved across interleaved diffs and findings.
  const all: TimelineItem[] = [];
  for (const d of diffs) all.push({ kind: 'diff', recordedAt: d.recordedAt ?? '', data: d });
  for (const f of findings) all.push({ kind: 'finding', recordedAt: f.recordedAt ?? '', data: f });

  // Stable chrono sort — same logic as the old buildTimeline.
  const sorted = all
    .map((it, idx) => ({ it, idx, key: it.recordedAt || '￿' }))
    .sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : a.idx - b.idx))
    .map(w => w.it);

  // Group while preserving first-seen order of test case titles so the rail
  // shows test cases in the order they started, not alphabetically.
  const groupMap = new Map<string, TimelineItem[]>();
  for (const item of sorted) {
    const title =
      item.kind === 'diff'
        ? (item.data.testCaseTitle?.trim() || UNGROUPED_LABEL)
        : (item.data.testCaseTitle?.trim() || UNGROUPED_LABEL);
    const bucket = groupMap.get(title);
    if (bucket) bucket.push(item);
    else groupMap.set(title, [item]);
  }

  return Array.from(groupMap.entries()).map(([title, items]) => ({
    title,
    isUngrouped: title === UNGROUPED_LABEL,
    items,
    mismatchCount: items.filter(i => i.kind === 'diff' && i.data.verdict === 'mismatch').length,
    failCount: items.filter(i => i.kind === 'finding' && i.data.type === 'fail').length,
  }));
}

// ─── types ────────────────────────────────────────────────────────────────────

type DiffItem = {
  kind: 'table_diff' | 'form_diff' | 'chart_diff' | 'section_diff' | 'style_diff';
  verdict: 'match' | 'mismatch';
  summary: string;
  artifactKey: string;
  testCaseTitle?: string;
  recordedAt?: string;
};

type FindingItem = {
  type: 'pass' | 'fail' | 'warning' | 'info';
  message: string;
  testCaseTitle: string;
  isBug?: boolean;
  recordedAt?: string;
  source?: 'ai' | 'replay';
};

type TimelineItem =
  | { kind: 'diff'; recordedAt: string; data: DiffItem }
  | { kind: 'finding'; recordedAt: string; data: FindingItem };

type TestCaseGroup = {
  title: string;
  isUngrouped: boolean;
  items: TimelineItem[];
  mismatchCount: number;
  failCount: number;
};

type StateView = {
  stateId: string;
  stateLabel: string;
  status: string;
  testCaseGroups: TestCaseGroup[];
  diffMismatchCount: number;
  findingFailCount: number;
  warnings: string[];
};

// ─── tone maps ────────────────────────────────────────────────────────────────

const FINDING_TONE = {
  fail:    { bar: 'bg-red-500',   badge: 'bg-red-500',   card: 'bg-red-50 border-red-200',    text: 'text-red-700',   icon: '✕' },
  warning: { bar: 'bg-amber-400', badge: 'bg-amber-500', card: 'bg-amber-50 border-amber-200', text: 'text-amber-700', icon: '!' },
  info:    { bar: 'bg-sky-400',   badge: 'bg-sky-500',   card: 'bg-sky-50 border-sky-200',    text: 'text-sky-700',   icon: 'i' },
  pass:    { bar: 'bg-green-500', badge: 'bg-green-500', card: 'bg-green-50 border-green-200', text: 'text-green-700', icon: '✓' },
} as const;

const DIFF_TONE = {
  match:    { bar: 'bg-green-500', card: 'bg-green-50 border-green-200', badge: 'bg-green-600', icon: '✓' },
  mismatch: { bar: 'bg-red-500',   card: 'bg-red-50 border-red-200',     badge: 'bg-red-600',   icon: '✕' },
} as const;

const STATUS_DOT: Record<string, string> = {
  passed:  'bg-green-500',
  failed:  'bg-red-500',
  running: 'bg-blue-500 animate-pulse',
  paused:  'bg-amber-400',
  pending: 'bg-gray-300',
};

// ─── individual timeline cards ────────────────────────────────────────────────

function DiffCard({ item, onDetail }: { item: DiffItem; onDetail: (key: string) => void }) {
  const tone = DIFF_TONE[item.verdict];
  const kindLabel = KIND_LABELS[item.kind] ?? item.kind;
  const clickable = !!item.artifactKey;

  return (
    <div
      onClick={() => clickable && onDetail(item.artifactKey)}
      className={`relative rounded-lg border ${tone.card} overflow-hidden transition-shadow ${clickable ? 'cursor-pointer hover:shadow-sm hover:border-gray-400' : ''}`}
      title={clickable ? `Click to view exact differences — ${item.artifactKey}` : undefined}
    >
      <div className={`absolute left-0 top-0 bottom-0 w-1 ${tone.bar} rounded-l-lg`} />
      <div className="pl-3 pr-2.5 py-2">
        <div className="flex items-start gap-2">
          <span className={`mt-0.5 shrink-0 w-4 h-4 rounded-full flex items-center justify-center text-[9px] font-black text-white ${tone.badge}`}>
            {tone.icon}
          </span>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5 flex-wrap">
              <span className={`text-[10px] font-bold uppercase tracking-wide ${item.verdict === 'match' ? 'text-green-700' : 'text-red-700'}`}>
                {item.verdict}
              </span>
              <span className="px-1.5 py-0.5 rounded text-[9px] font-semibold bg-gray-100 text-gray-500 border border-gray-200 uppercase tracking-wide">
                {kindLabel}
              </span>
              {clickable && (
                <span className="ml-auto text-[9px] text-gray-400 shrink-0">view details →</span>
              )}
            </div>
            {item.summary && (
              <p className="text-[10px] mt-0.5 text-gray-500 leading-snug line-clamp-2">{item.summary}</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function FindingCard({ item }: { item: FindingItem }) {
  const [expanded, setExpanded] = useState(false);
  const tone = FINDING_TONE[item.type];
  const hasMore = item.message.includes('\n') || item.message.length > TWO_LINE_CHAR_THRESHOLD;

  return (
    <div
      className={`relative rounded-lg border ${tone.card} overflow-hidden transition-shadow hover:shadow-sm`}
    >
      <div className={`absolute left-0 top-0 bottom-0 w-1 ${tone.bar} rounded-l-lg`} />
      <div className="pl-3 pr-2.5 py-2">
        <div className="flex items-start gap-2">
          <span className={`mt-0.5 shrink-0 w-4 h-4 rounded-full flex items-center justify-center text-[9px] font-black text-white ${tone.badge}`}>
            {tone.icon}
          </span>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5 flex-wrap">
              <span className={`text-[10px] font-bold uppercase tracking-wide ${tone.text}`}>
                {item.type}
              </span>
              {item.isBug && (
                <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-red-100 text-red-700 border border-red-200 uppercase tracking-wide">
                  bug
                </span>
              )}
              {item.source === 'replay' && (
                <span
                  className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-purple-100 text-purple-700 border border-purple-200 uppercase tracking-wide"
                  title="Generated by the engine during a replay run, not by the AI"
                >
                  replay
                </span>
              )}
            </div>
            <p className={`text-[11px] mt-0.5 leading-snug text-gray-800 ${!expanded ? 'line-clamp-2' : ''}`}>
              {item.message}
            </p>
            {hasMore && (
              <button
                onClick={(e) => { e.stopPropagation(); setExpanded(v => !v); }}
                className="mt-0.5 text-[10px] text-gray-400 hover:text-gray-600 cursor-pointer"
              >
                {expanded ? 'Show less ▲' : 'Show more ▼'}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── test case group within a state ──────────────────────────────────────────

function TestCaseGroupSection({
  group,
  onDetail,
}: {
  group: TestCaseGroup;
  onDetail: (key: string) => void;
}) {
  const [collapsed, setCollapsed] = useState(false);

  return (
    <div>
      <button
        onClick={() => setCollapsed(v => !v)}
        className="w-full flex items-center gap-1.5 px-1.5 py-1 rounded-md hover:bg-gray-100 transition-colors cursor-pointer group text-left"
      >
        {/* indented test-case label */}
        <span className="shrink-0 w-1 h-1 rounded-full bg-gray-300 ml-1" />
        <span className={`text-[10.5px] font-semibold flex-1 truncate leading-tight ${group.isUngrouped ? 'text-gray-400 italic' : 'text-gray-600'}`}>
          {group.title}
        </span>

        {/* per-TC summary chips */}
        <div className="flex items-center gap-1 shrink-0">
          {group.mismatchCount > 0 && (
            <span className="px-1 py-0.5 rounded-full text-[9px] font-bold bg-red-100 text-red-600">
              {group.mismatchCount} ✕
            </span>
          )}
          {group.failCount > 0 && (
            <span className="px-1 py-0.5 rounded-full text-[9px] font-bold bg-red-100 text-red-600">
              {group.failCount} fail
            </span>
          )}
          {group.mismatchCount === 0 && group.failCount === 0 && (
            <span className="px-1 py-0.5 rounded-full text-[9px] font-bold bg-green-100 text-green-600">✓</span>
          )}
        </div>

        <span className="text-gray-300 group-hover:text-gray-400 text-[9px] shrink-0 ml-0.5">
          {collapsed ? '▶' : '▼'}
        </span>
      </button>

      {!collapsed && (
        <div className="mt-1 pl-4 space-y-1.5 pb-0.5">
          {group.items.map((item, i) =>
            item.kind === 'diff' ? (
              <DiffCard key={`d-${item.data.artifactKey || i}`} item={item.data} onDetail={onDetail} />
            ) : (
              <FindingCard key={`f-${i}`} item={item.data} />
            ),
          )}
        </div>
      )}
    </div>
  );
}

// ─── per-state collapsible section ────────────────────────────────────────────

function StateSection({
  sv,
  onDetail,
  onDownload,
}: {
  sv: StateView;
  onDetail: (key: string) => void;
  onDownload: (stateId: string) => void;
}) {
  const [collapsed, setCollapsed] = useState(false);
  const dot = STATUS_DOT[sv.status] ?? STATUS_DOT.pending;
  const isRunning = sv.status === 'running';
  const totalItems = sv.testCaseGroups.reduce((s, g) => s + g.items.length, 0);

  return (
    <div>
      {/* state header */}
      <button
        onClick={() => setCollapsed(v => !v)}
        className="w-full flex items-center gap-2 px-2 py-1.5 rounded-lg hover:bg-gray-50 transition-colors cursor-pointer group text-left"
      >
        <span className={`shrink-0 w-2 h-2 rounded-full ${dot}`} />
        <span className="text-[11px] font-semibold text-gray-700 flex-1 truncate leading-tight">
          {sv.stateLabel}
        </span>

        {/* state summary chips */}
        <div className="flex items-center gap-1 shrink-0">
          {sv.diffMismatchCount > 0 && (
            <span className="px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-red-100 text-red-600">
              {sv.diffMismatchCount} ✕
            </span>
          )}
          {sv.findingFailCount > 0 && (
            <span className="px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-red-100 text-red-600">
              {sv.findingFailCount} fail
            </span>
          )}
          {sv.diffMismatchCount === 0 && sv.findingFailCount === 0 && totalItems > 0 && (
            <span className="px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-green-100 text-green-600">
              all match
            </span>
          )}
        </div>

        <button
          onClick={(e) => { e.stopPropagation(); onDownload(sv.stateId); }}
          className="shrink-0 text-[9px] font-semibold text-gray-400 hover:text-orange-600 cursor-pointer px-1 py-0.5 rounded hover:bg-orange-50 transition-colors"
          title="Download HTML report for this state"
        >
          ⤓
        </button>

        <span className="text-gray-300 group-hover:text-gray-400 text-[10px] shrink-0">
          {collapsed ? '▶' : '▼'}
        </span>
      </button>

      {/* test-case groups */}
      {!collapsed && (
        <div className="mt-1 pl-2 pb-1 space-y-0.5">
          {totalItems === 0 && isRunning && (
            <div className="flex items-center gap-1.5 py-1.5 px-2">
              <div className="w-3 h-3 border-2 border-blue-300 border-t-blue-500 rounded-full animate-spin shrink-0" />
              <span className="text-[10px] text-gray-400 italic">Comparing…</span>
            </div>
          )}
          {totalItems === 0 && !isRunning && (
            <p className="text-[10px] text-gray-400 italic py-1 px-2">No diffs recorded.</p>
          )}

          {sv.testCaseGroups.map((group, gi) => (
            <div key={group.title}>
              <TestCaseGroupSection group={group} onDetail={onDetail} />
              {gi < sv.testCaseGroups.length - 1 && (
                <div className="my-1 ml-2 mr-1 h-px bg-gray-100" />
              )}
            </div>
          ))}

          {sv.warnings.length > 0 && (
            <div className="mt-2 mx-1 text-[10px] text-orange-700 bg-orange-50 border border-orange-200 rounded-lg p-2 space-y-0.5">
              {sv.warnings.map((w, i) => (
                <div key={i} className="flex items-start gap-1">
                  <span className="shrink-0">⚠</span>
                  <span>{w}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ─── root component ───────────────────────────────────────────────────────────

export default function DiffResultsRail({ run, mode = 'live' }: { run: ComparisonRun | null; mode?: 'live' | 'history' }) {
  const liveDiffsFromStore = useStore((s) => s.comparisonLiveDiffs);
  const liveTestCasesFromStore = useStore((s) => s.comparisonTestCasesByState);
  const liveDiffs = mode === 'history' ? EMPTY_LIVE_DIFFS : liveDiffsFromStore;
  const liveTestCases = mode === 'history' ? EMPTY_TEST_CASES : liveTestCasesFromStore;
  const activator = useActivator();
  const [detailArtifactKey, setDetailArtifactKey] = useState<string | null>(null);

  const statesView = useMemo<StateView[]>(() => {
    if (!run) return [];

    const seenStateIds = new Set<string>();
    const out: StateView[] = [];

    for (const sr of run.stateResults) {
      seenStateIds.add(sr.stateId);
      const persistedDiffsWithTimestamp = backfillDiffTimestamps(sr.diffs, sr.testCases ?? []);
      const diffs = mergeDiffs(persistedDiffsWithTimestamp, liveDiffs[sr.stateId] ?? []);
      const findings = dedupeFindings([
        ...extractFindingsFromTestCases(sr.testCases ?? []),
        ...extractFindingsFromTestCases(liveTestCases[sr.stateId] ?? []),
      ]);
      const testCaseGroups = groupByTestCase(diffs, findings);
      out.push({
        stateId: sr.stateId,
        stateLabel: sr.stateLabel,
        status: sr.status,
        testCaseGroups,
        diffMismatchCount: diffs.filter((d) => d.verdict === 'mismatch').length,
        findingFailCount: findings.filter((f) => f.type === 'fail').length,
        warnings: sr.warnings,
      });
    }

    const liveOnlyStateIds = new Set<string>();
    for (const stateId of Object.keys(liveDiffs)) if (!seenStateIds.has(stateId)) liveOnlyStateIds.add(stateId);
    for (const stateId of Object.keys(liveTestCases)) if (!seenStateIds.has(stateId)) liveOnlyStateIds.add(stateId);
    for (const stateId of liveOnlyStateIds) {
      const diffs = (liveDiffs[stateId] ?? []) as DiffItem[];
      const findings = dedupeFindings(extractFindingsFromTestCases(liveTestCases[stateId] ?? []));
      const testCaseGroups = groupByTestCase(diffs, findings);
      out.push({
        stateId,
        stateLabel: run.plan?.states?.find((s) => s.id === stateId)?.label ?? stateId,
        status: 'running',
        testCaseGroups,
        diffMismatchCount: diffs.filter((d) => d.verdict === 'mismatch').length,
        findingFailCount: findings.filter((f) => f.type === 'fail').length,
        warnings: [],
      });
    }
    return out;
  }, [run, liveDiffs, liveTestCases]);

  const totalMismatches = statesView.reduce((acc, s) => acc + s.diffMismatchCount, 0);
  const totalFailFindings = statesView.reduce((acc, s) => acc + s.findingFailCount, 0);
  const totalItems = statesView.reduce((acc, s) => s.testCaseGroups.reduce((gs, g) => gs + g.items.length, acc), 0);

  if (!run) {
    return (
      <div className="rounded-2xl border border-gray-200 bg-white flex flex-col h-full">
        <div className="px-3.5 pt-3 pb-2.5 border-b border-gray-100">
          <h3 className="text-xs font-bold text-gray-800 tracking-tight">Differences</h3>
          <p className="text-[10px] text-gray-400 mt-1">No run in progress.</p>
        </div>
        <div className="flex-1 flex flex-col items-center justify-center py-10 text-center select-none">
          <span className="text-3xl mb-2 opacity-20">⇄</span>
          <p className="text-[11px] text-gray-400 font-medium">No comparison run</p>
        </div>
      </div>
    );
  }

  return (
    <div className="rounded-2xl border border-gray-200 bg-white flex flex-col min-h-0 h-full max-h-[calc(100vh-40px)]">
      {/* Rail header */}
      <div className="px-3.5 pt-3 pb-2.5 border-b border-gray-100">
        <div className="flex items-center justify-between gap-2">
          <h3 className="text-xs font-bold text-gray-800 tracking-tight">Differences</h3>
          <div className="flex items-center gap-1">
            <button
              onClick={() => activator.downloadComparisonReport(run.id, undefined, 'html')}
              className="text-[10px] font-semibold text-orange-600 hover:text-orange-700 cursor-pointer px-1.5 py-0.5 rounded hover:bg-orange-50 transition-colors"
              title="Download styled HTML report for the full run"
            >
              ⤓ HTML
            </button>
            <button
              onClick={() => activator.downloadComparisonReport(run.id, undefined, 'markdown')}
              className="text-[10px] font-semibold text-gray-500 hover:text-gray-700 cursor-pointer px-1.5 py-0.5 rounded hover:bg-gray-50 transition-colors"
              title="Download Markdown report for the full run"
            >
              .md
            </button>
          </div>
        </div>

        {totalItems > 0 ? (
          <div className="flex items-center gap-1.5 mt-1.5 flex-wrap">
            {totalMismatches > 0 && (
              <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-red-100 text-red-600">
                {totalMismatches} mismatch{totalMismatches !== 1 ? 'es' : ''}
              </span>
            )}
            {totalFailFindings > 0 && (
              <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-red-100 text-red-600">
                {totalFailFindings} fail{totalFailFindings !== 1 ? 's' : ''}
              </span>
            )}
            {totalMismatches === 0 && totalFailFindings === 0 && (
              <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-green-100 text-green-600">
                All matching ✓
              </span>
            )}
            <span className="text-[10px] text-gray-400">
              {totalItems} item{totalItems !== 1 ? 's' : ''} · {statesView.length} state{statesView.length !== 1 ? 's' : ''}
            </span>
          </div>
        ) : (
          <p className="text-[10px] text-gray-400 mt-1">Diffs will appear here as the AI discovers them.</p>
        )}
      </div>

      {/* Scrollable content */}
      <div className="flex-1 overflow-y-auto px-2 py-2 space-y-1" style={{ minHeight: 0 }}>
        {statesView.length === 0 && (
          <div className="flex flex-col items-center justify-center py-10 text-center select-none">
            <span className="text-3xl mb-2 opacity-20">⇄</span>
            <p className="text-[11px] text-gray-400 font-medium">No states yet</p>
            <p className="text-[10px] text-gray-300 mt-0.5">Results stream in as each state is compared</p>
          </div>
        )}

        {statesView.map((sv, idx) => (
          <div key={sv.stateId}>
            <StateSection
              sv={sv}
              onDetail={setDetailArtifactKey}
              onDownload={(stateId) => activator.downloadComparisonReport(run.id, stateId, 'html')}
            />
            {idx < statesView.length - 1 && (
              <div className="my-1.5 mx-2 h-px bg-linear-to-r from-transparent via-gray-200 to-transparent" />
            )}
          </div>
        ))}
      </div>

      {detailArtifactKey && (
        <ComparisonDiffDetailModal
          artifactKey={detailArtifactKey}
          runId={run.id}
          sideLabels={{
            left: run.plan?.sides[0]?.label || 'left',
            right: run.plan?.sides[1]?.label || 'right',
          }}
          runDetail={mode === 'history' ? run : undefined}
          onClose={() => setDetailArtifactKey(null)}
        />
      )}
    </div>
  );
}
