import { useStore } from '../../store/state';
import type { SessionState } from '../../../activator/types/state';
import type { ComparisonSideConfig } from '../../../activator/types/comparisonPlan';

const EMPTY_SESSIONS: NonNullable<SessionState['browserSessions']> = [];

/**
 * Live list of open browser sessions, paired with the plan's side metadata.
 * Renders each session as a tile with its url, title, active state, and
 * — future iteration — a live screenshot thumbnail.
 *
 * For now we display session metadata; the activator broadcasts
 * `browserSessionsChanged` with url/title from the manager. Live screenshot
 * polling is deferred to a later iteration because it needs a targeted
 * server-side push mechanism (adding it now would require another round of
 * activator changes and feels out of scope for this UI chunk).
 */
export default function BrowserSessionsPanel({ sides }: { sides: ComparisonSideConfig[] }) {
  const sessions = useStore((s) => s.session.browserSessions) ?? EMPTY_SESSIONS;
  const activeId = useStore((s) => s.session.activeBrowserSessionId);

  if (sessions.length === 0) {
    return <p className="text-[11px] text-gray-400">No browsers open yet — launching…</p>;
  }

  return (
    <div className="flex flex-wrap items-center gap-1.5">
      {sessions.map((s) => {
        const side = sides.find((x) => x.sessionId === s.id);
        const isActive = s.id === activeId;
        return (
          <div
            key={s.id}
            className={`flex items-center gap-1.5 rounded-md border px-2 py-1 min-w-0 max-w-full sm:max-w-80 ${
              isActive ? 'border-orange-400 bg-orange-50/60' : 'border-gray-200 bg-white'
            }`}
          >
            <span className="inline-block w-1.5 h-1.5 rounded-full bg-green-500 shrink-0" />
            <span className="text-xs font-semibold text-gray-800 shrink-0">{side?.label ?? s.id}</span>
            <span className="text-[9px] uppercase text-gray-400 tracking-wide font-mono shrink-0">{s.id}</span>
            {s.url && (
              <span className="text-[11px] text-gray-500 truncate font-mono min-w-0" title={`${s.url}${s.title ? `\n${s.title}` : ''}`}>
                {s.url.replace(/^https?:\/\//, '')}
              </span>
            )}
            <span className="text-[10px] text-gray-400 shrink-0 ml-auto">{s.driverType}</span>
            <span className="text-[10px] text-gray-400 shrink-0">·</span>
            <span className="text-[10px] text-gray-400 shrink-0">{s.headless ? 'headless' : 'visible'}</span>
            <span className="text-[10px] text-gray-400 shrink-0 hidden md:inline">·</span>
            <span className="text-[10px] text-gray-400 shrink-0 hidden md:inline">{new Date(s.createdAt).toLocaleTimeString()}</span>
            {isActive && <span className="text-[9px] uppercase text-orange-600 font-bold shrink-0">live</span>}
          </div>
        );
      })}
    </div>
  );
}
