import { useCallback, useEffect, useRef, useState } from 'react';
import { useStore } from '../store/state';
import { useActivator } from '../store/Context';
import type { AncestorNode } from '../../activator/types/state';

interface Props {
  open: boolean;
  initialUrl?: string;
  context: 'module' | 'comparison-old' | 'comparison-new' | 'generic';
  onResult: (result: { xpath: string; url: string; bestSelector: string }) => void;
  onClose: () => void;
}

function AncestorTree({ chain, sessionId }: { chain: AncestorNode[]; sessionId?: string }) {
  const activator = useActivator();
  const [selected, setSelected] = useState(0);
  const highlightTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleMouseEnter = useCallback((xpath: string) => {
    if (!sessionId) return;
    if (highlightTimer.current) clearTimeout(highlightTimer.current);
    // Small debounce so fast mouse passes don't spam WS
    highlightTimer.current = setTimeout(() => {
      activator.highlightPickerNode(sessionId, xpath);
    }, 60);
  }, [activator, sessionId]);

  const handleMouseLeave = useCallback(() => {
    if (!sessionId) return;
    if (highlightTimer.current) clearTimeout(highlightTimer.current);
    highlightTimer.current = setTimeout(() => {
      activator.highlightPickerNode(sessionId, '');
    }, 120);
  }, [activator, sessionId]);

  const handleSelect = useCallback((index: number, xpath: string) => {
    setSelected(index);
    if (sessionId) activator.reselectPickerNode(sessionId, xpath);
  }, [activator, sessionId]);

  return (
    <div className="mt-3">
      <div className="text-xs font-medium text-gray-500 mb-1.5">Element hierarchy — click any ancestor to select it</div>
      <div className="border border-gray-200 rounded-lg overflow-hidden">
        {chain.map((node, i) => {
          const isSelected = i === selected;
          const depth = i;
          return (
            <button
              key={node.xpath}
              type="button"
              onMouseEnter={() => handleMouseEnter(node.xpath)}
              onMouseLeave={handleMouseLeave}
              onClick={() => handleSelect(i, node.xpath)}
              className={`w-full text-left flex items-center gap-2 px-3 py-1.5 text-xs transition cursor-pointer border-b border-gray-100 last:border-b-0 ${
                isSelected
                  ? 'bg-orange-50 text-orange-700 font-semibold'
                  : 'hover:bg-gray-50 text-gray-700'
              }`}
              style={{ paddingLeft: `${12 + depth * 12}px` }}
            >
              <span className={`font-mono text-[10px] px-1 py-0.5 rounded ${isSelected ? 'bg-orange-100 text-orange-700' : 'bg-gray-100 text-gray-500'}`}>
                {`<${node.tag}>`}
              </span>
              {node.id && (
                <span className="text-blue-600 font-mono text-[10px]">#{node.id}</span>
              )}
              <span className="truncate text-gray-500 text-[10px]">{node.label}</span>
              {i === 0 && (
                <span className="ml-auto text-[9px] px-1.5 py-0.5 rounded-full bg-orange-100 text-orange-600 font-semibold shrink-0">clicked</span>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export default function ElementPickerModal({ open, initialUrl, context, onResult, onClose }: Props) {
  const activator = useActivator();
  const status = useStore(s => s.pickerStatus);
  const result = useStore(s => s.lastPickerResult);
  const error = useStore(s => s.pickerError);
  const setPickerStatus = useStore(s => s.setPickerStatus);
  const setLastPickerResult = useStore(s => s.setLastPickerResult);
  const setPickerError = useStore(s => s.setPickerError);

  useEffect(() => {
    if (!open) return;
    setPickerStatus('launching');
    setLastPickerResult(null);
    setPickerError(null);
    activator.startPicker({ initialUrl, context });
    return () => {
      activator.cancelPicker();
      setPickerStatus('idle');
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  if (!open) return null;

  const handleDone = () => {
    if (result) {
      onResult({ xpath: result.xpath, url: result.url, bestSelector: result.bestSelector });
    }
    onClose();
  };

  const handlePickAnother = () => {
    setPickerStatus('launching');
    setLastPickerResult(null);
    activator.startPicker({ context });
  };

  const handleCancel = () => {
    activator.cancelPicker();
    onClose();
  };

  const activeSelector = result?.bestSelector || result?.xpath || '';
  const ancestorChain = result?.ancestorChain ?? [];

  return (
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">
      <div className="bg-white rounded-2xl p-6 w-full max-w-xl shadow-xl max-h-[90vh] overflow-y-auto">
        <h3 className="text-base font-semibold text-gray-800 mb-3">Pick an element</h3>

        {status === 'launching' && (
          <p className="text-sm text-gray-500">Launching browser...</p>
        )}
        {status === 'waiting' && (
          <p className="text-sm text-gray-600">
            Hover and click the element you want to capture in the browser window. You can navigate freely — the picker stays active.
          </p>
        )}

        {status === 'picked' && result && (
          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <span className="text-sm text-green-700 font-semibold">Element captured</span>
            </div>

            <div>
              <div className="text-xs font-medium text-gray-500 mb-1">Best selector</div>
              <pre className="text-xs bg-gray-50 border border-gray-200 rounded p-2 overflow-x-auto whitespace-pre-wrap break-all">{activeSelector}</pre>
            </div>

            {ancestorChain.length > 0 && (
              <AncestorTree chain={ancestorChain} sessionId={result.sessionId} />
            )}

            <div>
              <div className="text-xs font-medium text-gray-500 mb-1">XPath</div>
              <pre className="text-xs bg-gray-50 border border-gray-200 rounded p-2 overflow-x-auto whitespace-pre-wrap break-all text-gray-500">{result.xpath}</pre>
            </div>
          </div>
        )}

        {status === 'error' && error && (
          <div className="text-sm text-red-600">Error: {error}</div>
        )}

        <div className="flex gap-2 mt-4 justify-end">
          {status === 'picked' && (
            <button
              onClick={handlePickAnother}
              className="px-3 py-1.5 text-xs bg-gray-100 text-gray-700 rounded-md hover:bg-gray-200 cursor-pointer"
            >
              Pick another
            </button>
          )}
          {status === 'picked' ? (
            <button
              onClick={handleDone}
              className="px-3 py-1.5 text-xs bg-orange-500 text-white rounded-md hover:bg-orange-600 font-semibold cursor-pointer"
            >
              Done
            </button>
          ) : (
            <button
              onClick={handleCancel}
              className="px-3 py-1.5 text-xs bg-gray-100 text-gray-700 rounded-md hover:bg-gray-200 cursor-pointer"
            >
              Cancel
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
