import classnames from 'classnames';
import { useEffect, useMemo, useState } from 'react';
import { useStore } from '../../store/state';
import { useActivator } from '../../store/Context';
import type {
  ComparisonRun,
  ComparisonRunSummary,
  ComparisonStateResult,
  ComparisonStep,
  ComparisonTestCase,
} from '../../../activator/types/comparisonPlan';
import ComparisonStepDetailModal from './ComparisonStepDetailModal';
import ComparisonStepRow from './ComparisonStepRow';
import DiffResultsRail from './DiffResultsRail';
import LogCountBadges from '../../components/network/LogCountBadges';
import { aggregateLogCounts, countStepLogs } from '../../components/network/stepCounts';
import TokenUsagePanel from '../workflow-tests/components/TokenUsagePanel';

interface SelectedHistoryStep {
  step: ComparisonStep;
  runId: string;
  stateId: string;
  testCaseId: string;
}

interface Props {
  projectId: string;
  moduleId: string;
  featureId?: string;
}

/**
 * Scoped history of past comparison runs. Shows up to 20 per scope (module,
 * or feature when featureId is present). Entries can be opened for a detailed
 * read-only view, downloaded as Markdown, or deleted with confirmation.
 */
export default function ComparisonHistoryView({ projectId, moduleId, featureId }: Props) {
  const scopeKey = `${projectId}:${moduleId}:${featureId ?? ''}`;
  const scopedHistory = useStore((s) => s.comparisonHistoryByScope[scopeKey]);
  const projects = useStore((s) => s.projects);
  const loadedRuns = useStore((s) => s.comparisonLoadedRuns);
  const activator = useActivator();
  const [expandedRunId, setExpandedRunId] = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [confirmReplayId, setConfirmReplayId] = useState<string | null>(null);

  // Prefer the live scope cache; fall back to whatever is embedded in the
  // state-synced project/module/feature so the list appears on first mount
  // without waiting for a dedicated broadcast.
  const history: ComparisonRunSummary[] = useMemo(() => {
    if (scopedHistory) return scopedHistory;
    const project = projects.find((p) => p.id === projectId);
    const mod = project?.modules.find((m) => m.id === moduleId);
    if (featureId) {
      const feature = mod?.features.find((f) => f.id === featureId);
      return feature?.comparisonHistory ?? [];
    }
    return mod?.comparisonHistory ?? [];
  }, [scopedHistory, projects, projectId, moduleId, featureId]);

  useEffect(() => {
    if (!expandedRunId) return;
    if (loadedRuns[expandedRunId]) return;
    const requestId = `cmpload_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    activator.loadComparisonRunDetail(requestId, expandedRunId);
  }, [expandedRunId, loadedRuns, activator]);

  const handleDelete = (runId: string) => {
    if (confirmDeleteId !== runId) {
      setConfirmDeleteId(runId);
      return;
    }
    activator.deleteComparisonRun(projectId, moduleId, featureId, runId);
    setConfirmDeleteId(null);
    if (expandedRunId === runId) setExpandedRunId(null);
  };

  const handleReplay = (runId: string) => {
    if (confirmReplayId !== runId) {
      setConfirmReplayId(runId);
      return;
    }
    activator.replayComparisonRun(runId);
    setConfirmReplayId(null);
  };

  if (history.length === 0) {
    return (
      <div className="rounded-2xl border border-dashed border-gray-300 bg-gray-50 p-6 text-center text-sm text-gray-500">
        No past comparison runs. Once you run a comparison, the last 20 runs for this scope show up here for review and download.
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <p className="text-xs text-gray-500">
        Last {history.length} comparison run{history.length === 1 ? '' : 's'} for this {featureId ? 'feature' : 'module'}. The oldest
        rolls off automatically when the 20-run cap is hit.
      </p>
      {history.map((entry) => {
        const expanded = expandedRunId === entry.id;
        const detail = loadedRuns[entry.id];
        return (
          <div key={entry.id} className="rounded-2xl border border-gray-200 bg-white">
            <button
              type="button"
              onClick={() => setExpandedRunId(expanded ? null : entry.id)}
              className={classnames(
                'w-full flex items-center justify-between gap-3 px-4 py-3 cursor-pointer hover:bg-gray-50 text-left rounded-t-2xl',
                { 'rounded-b-2xl': !expanded },
              )}
            >
              <div className="flex items-center gap-3 min-w-0">
                <span
                  className={`px-1.5 py-0.5 rounded text-[10px] uppercase font-semibold text-white ${
                    entry.status === 'passed' ? 'bg-green-600' : entry.status === 'failed' ? 'bg-red-600' : 'bg-gray-500'
                  }`}
                >
                  {entry.status}
                </span>
                <div className="min-w-0">
                  <p className="text-sm font-semibold text-gray-800 truncate flex items-center gap-1.5">
                    {entry.planTitle || entry.planId}
                    {entry.replay && (
                      <span
                        className="px-1.5 py-0.5 rounded text-[10px] uppercase font-semibold bg-purple-100 text-purple-700 border border-purple-200 shrink-0"
                        title={`Replay of run started ${new Date(entry.replay.ofStartedAt).toLocaleString()}`}
                      >
                        ↻ replay of {new Date(entry.replay.ofStartedAt).toLocaleDateString()}
                      </span>
                    )}
                  </p>
                  <p className="text-[11px] text-gray-500 truncate">
                    {new Date(entry.startedAt).toLocaleString()} · {entry.totalStates} state{entry.totalStates === 1 ? '' : 's'} ·{' '}
                    {entry.totalTestCases} test case{entry.totalTestCases === 1 ? '' : 's'} · {entry.mismatchCount} mismatch
                    {entry.mismatchCount === 1 ? '' : 'es'}
                    {entry.sideLabels.length > 0 && <> · {entry.sideLabels.join(' vs ')}</>}
                    {entry.totalCostUSD !== undefined && entry.totalCostUSD > 0 && (
                      <> · <span className="text-gray-700 font-medium">${entry.totalCostUSD < 0.01 ? entry.totalCostUSD.toFixed(4) : entry.totalCostUSD.toFixed(3)}</span></>
                    )}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <span
                  onClick={(e) => {
                    e.stopPropagation();
                    handleReplay(entry.id);
                  }}
                  className={`text-[11px] font-semibold cursor-pointer ${
                    confirmReplayId === entry.id ? 'text-purple-800 underline' : 'text-purple-600 hover:text-purple-700'
                  }`}
                  title={
                    confirmReplayId === entry.id
                      ? 'Click again to confirm: launches browsers and re-runs all recorded steps. Findings from the original run are not carried over.'
                      : 'Replay this run — re-execute the recorded steps against the live page; findings are regenerated from fresh diff verdicts (no AI in the loop).'
                  }
                >
                  {confirmReplayId === entry.id ? 'Confirm replay' : '↻ Replay'}
                </span>
                <span
                  onClick={(e) => {
                    e.stopPropagation();
                    activator.downloadComparisonReport(entry.id, undefined, 'html');
                  }}
                  className="text-[11px] font-semibold text-orange-600 hover:text-orange-700 cursor-pointer"
                  title="Download styled HTML report"
                >
                  ⤓ HTML
                </span>
                <span
                  onClick={(e) => {
                    e.stopPropagation();
                    activator.downloadComparisonReport(entry.id, undefined, 'markdown');
                  }}
                  className="text-[11px] font-semibold text-gray-500 hover:text-gray-700 cursor-pointer"
                  title="Download Markdown report"
                >
                  .md
                </span>
                <span
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDelete(entry.id);
                  }}
                  className={`text-[11px] font-semibold cursor-pointer ${
                    confirmDeleteId === entry.id ? 'text-red-800 underline' : 'text-red-600 hover:text-red-700'
                  }`}
                  title={confirmDeleteId === entry.id ? 'Click again to confirm' : 'Delete this run'}
                >
                  {confirmDeleteId === entry.id ? 'Confirm delete' : 'Delete'}
                </span>
                <span className="text-xs text-gray-400">{expanded ? '▾' : '▸'}</span>
              </div>
            </button>
            {expanded && (
              <div className="px-4 pb-4 border-t border-gray-100 rounded-b-2xl">
                {!detail && <p className="text-xs text-gray-500 mt-3">Loading run details…</p>}
                {detail && <RunDetail run={detail} />}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

const TC_STATUS_BADGE: Record<ComparisonTestCase['status'], string> = {
  pending: 'bg-gray-200 text-gray-700',
  running: 'bg-orange-100 text-orange-700',
  passed: 'bg-green-100 text-green-700',
  failed: 'bg-red-100 text-red-700',
  skipped: 'bg-gray-100 text-gray-500',
};

function RunDetail({ run }: { run: ComparisonRun }) {
  const [selectedStep, setSelectedStep] = useState<SelectedHistoryStep | null>(null);

  return (
    <>
      {run.tokenUsage && run.tokenUsage.length > 0 && (
        <div className="mt-3">
          <TokenUsagePanel entries={run.tokenUsage} title="Token Usage" />
        </div>
      )}
      <div className="grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_320px] gap-4 pt-3">
        <div className="space-y-3 text-xs min-w-0">
          {run.stateResults.map((sr) => (
            <StateBlock
              key={sr.stateId}
              sr={sr}
              onStepClick={(step, testCaseId) =>
                setSelectedStep({ step, runId: run.id, stateId: sr.stateId, testCaseId })
              }
            />
          ))}
        </div>
        <div className="min-w-0 h-96 lg:h-[calc(100vh-1.5rem)] lg:self-start lg:sticky lg:top-3">
          <DiffResultsRail run={run} mode="history" />
        </div>
      </div>
      {selectedStep && (
        <ComparisonStepDetailModal
          step={selectedStep.step}
          runContext={{
            runId: selectedStep.runId,
            stateId: selectedStep.stateId,
            testCaseId: selectedStep.testCaseId,
          }}
          onClose={() => setSelectedStep(null)}
        />
      )}
    </>
  );
}

function StateBlock({
  sr,
  onStepClick,
}: {
  sr: ComparisonStateResult;
  onStepClick: (s: ComparisonStep, testCaseId: string) => void;
}) {
  return (
    <div className="border border-gray-200 rounded-lg p-3">
      <div className="flex items-center gap-2 mb-2">
        <span className="text-sm font-semibold text-gray-800">{sr.stateLabel}</span>
        <span
          className={`px-1.5 py-0.5 rounded text-[10px] uppercase font-semibold text-white ${
            sr.status === 'passed' ? 'bg-green-600' : sr.status === 'failed' ? 'bg-red-600' : 'bg-gray-500'
          }`}
        >
          {sr.status}
        </span>
        <span className="text-[11px] text-gray-500">
          {sr.testCases.length} test case{sr.testCases.length === 1 ? '' : 's'} · {sr.diffs.length} diff
          {sr.diffs.length === 1 ? '' : 's'}
        </span>
      </div>
      {sr.testCases.length > 0 && (
        <div className="space-y-2">
          {sr.testCases.map((tc) => (
            <HistoryTestCaseCard key={tc.id} testCase={tc} onStepClick={onStepClick} />
          ))}
        </div>
      )}
    </div>
  );
}

function HistoryTestCaseCard({
  testCase,
  onStepClick,
}: {
  testCase: ComparisonTestCase;
  onStepClick: (s: ComparisonStep, testCaseId: string) => void;
}) {
  const [expanded, setExpanded] = useState<boolean>(testCase.status === 'failed');
  const aggregateCounts = useMemo(
    () => aggregateLogCounts(testCase.steps.map((s) => countStepLogs(s.networkRequests, s.consoleMessages))),
    [testCase.steps],
  );

  return (
    <div className="border border-gray-200 rounded-md bg-white">
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        className="w-full flex items-center justify-between gap-2 px-3 py-2 text-left cursor-pointer hover:bg-gray-50"
      >
        <div className="flex items-center gap-2 min-w-0 flex-1">
          <span
            className={classnames(
              'shrink-0 text-[10px] uppercase font-semibold tracking-wide px-1.5 py-0.5 rounded',
              TC_STATUS_BADGE[testCase.status],
            )}
          >
            {testCase.status}
          </span>
          <span className="text-xs font-semibold text-gray-800 truncate">{testCase.title}</span>
          <span className="shrink-0 text-[10px] text-gray-400">
            {testCase.steps.length} step{testCase.steps.length === 1 ? '' : 's'}
          </span>
          <LogCountBadges counts={aggregateCounts} size="spread" />
        </div>
        <span className="text-xs text-gray-400 shrink-0">{expanded ? '▾' : '▸'}</span>
      </button>
      {testCase.description && <p className="px-3 pb-1 text-[11px] text-gray-600">{testCase.description}</p>}
      {testCase.summary && <p className="px-3 pb-2 text-[11px] text-gray-500 italic">{testCase.summary}</p>}
      {expanded && (
        <div className="px-3 pb-3 space-y-1">
          {testCase.steps.length === 0 ? (
            <p className="text-[11px] text-gray-400">No steps were recorded for this test case.</p>
          ) : (
            testCase.steps.map((step, idx) => (
              <ComparisonStepRow key={step.id} step={step} index={idx + 1} onClick={() => onStepClick(step, testCase.id)} />
            ))
          )}
        </div>
      )}
    </div>
  );
}
