import type { NetworkRequestSummary, ConsoleMessageSummary } from '../../../activator/types/state';

export interface StepLogCounts {
  networkCount: number;
  networkErrorCount: number;
  consoleErrorCount: number;
  consoleWarnCount: number;
  consoleInfoCount: number;
}

export function countStepLogs(
  network: NetworkRequestSummary[] | undefined,
  console: ConsoleMessageSummary[] | undefined,
): StepLogCounts {
  const counts: StepLogCounts = {
    networkCount: 0,
    networkErrorCount: 0,
    consoleErrorCount: 0,
    consoleWarnCount: 0,
    consoleInfoCount: 0,
  };
  if (network) {
    counts.networkCount = network.length;
    for (const r of network) {
      if (r.failed || (r.status ?? 0) >= 400) counts.networkErrorCount++;
    }
  }
  if (console) {
    for (const m of console) {
      if (m.type === 'error') counts.consoleErrorCount++;
      else if (m.type === 'warn') counts.consoleWarnCount++;
      else counts.consoleInfoCount++;
    }
  }
  return counts;
}

export function aggregateLogCounts(perStep: StepLogCounts[]): StepLogCounts {
  const total: StepLogCounts = {
    networkCount: 0,
    networkErrorCount: 0,
    consoleErrorCount: 0,
    consoleWarnCount: 0,
    consoleInfoCount: 0,
  };
  for (const c of perStep) {
    total.networkCount += c.networkCount;
    total.networkErrorCount += c.networkErrorCount;
    total.consoleErrorCount += c.consoleErrorCount;
    total.consoleWarnCount += c.consoleWarnCount;
    total.consoleInfoCount += c.consoleInfoCount;
  }
  return total;
}
