import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import {
    CAPABILITY_HINT,
    CAPABILITY_LABEL,
    type ModelCapability,
    type ModelInfo,
    type TaskKey,
    TASK_REQUIREMENTS,
    evaluateModelForTask,
} from './modelCatalog';

export { modelInfosFor, modelsFor } from './modelCatalog';
export type { ModelCapability, ModelInfo, TaskKey } from './modelCatalog';

// ─── Building blocks shared across the settings page ───────────────────────────

export function SectionCard({
    title,
    icon,
    children,
    action,
}: {
    title: string;
    icon: string;
    children: React.ReactNode;
    action?: React.ReactNode;
}) {
    return (
        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
            <div className="flex items-center gap-3 px-6 py-4 border-b border-gray-100 bg-gray-50/60">
                <span className="text-xl">{icon}</span>
                <h2 className="text-sm font-semibold text-gray-800 tracking-wide uppercase">{title}</h2>
                {action && <div className="ml-auto">{action}</div>}
            </div>
            <div className="p-6">{children}</div>
        </div>
    );
}

export function Field({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) {
    return (
        <div className="flex flex-col gap-1">
            <label className="text-xs font-medium text-gray-600">{label}</label>
            {hint && <p className="text-[11px] text-gray-400 leading-snug">{hint}</p>}
            {children}
        </div>
    );
}

export function TextInput({
    value,
    onChange,
    placeholder,
    type = 'text',
    mono = false,
}: {
    value: string;
    onChange: (v: string) => void;
    placeholder?: string;
    type?: string;
    mono?: boolean;
}) {
    return (
        <input
            type={type}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            placeholder={placeholder}
            className={`w-full px-3 py-2 rounded-lg border border-gray-200 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-orange-300 focus:border-orange-400 transition-all placeholder:text-gray-300 ${mono ? 'font-mono' : ''}`}
        />
    );
}

export function Toggle({ checked, onChange, label }: { checked: boolean; onChange: (v: boolean) => void; label?: string }) {
    return (
        <label className="flex items-center gap-2 cursor-pointer select-none">
            <button
                type="button"
                role="switch"
                aria-checked={checked}
                onClick={() => onChange(!checked)}
                className={`relative w-9 h-5 rounded-full transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-orange-300 cursor-pointer ${checked ? 'bg-orange-500' : 'bg-gray-200'}`}
            >
                <span
                    className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow transition-transform duration-200 ${checked ? 'translate-x-4' : 'translate-x-0'}`}
                />
            </button>
            {label && <span className="text-xs text-gray-600">{label}</span>}
        </label>
    );
}

export function SegmentedControl<T extends string>({
    options,
    value,
    onChange,
}: {
    options: { value: T; label: string; desc?: string }[];
    value: T;
    onChange: (v: T) => void;
}) {
    return (
        <div className="flex flex-wrap gap-2">
            {options.map((opt) => (
                <button
                    key={opt.value}
                    type="button"
                    onClick={() => onChange(opt.value)}
                    className={`px-3 py-1.5 rounded-lg border text-xs font-medium transition-all duration-150 cursor-pointer ${
                        value === opt.value
                            ? 'border-orange-400 bg-orange-50 text-orange-700 shadow-sm shadow-orange-100'
                            : 'border-gray-200 bg-white text-gray-600 hover:border-gray-300'
                    }`}
                >
                    {opt.label}
                    {opt.desc && <span className="ml-1 text-[10px] text-gray-400 font-normal">({opt.desc})</span>}
                </button>
            ))}
        </div>
    );
}

// ─── Capability badges ────────────────────────────────────────────────────────

const CAP_BADGE_CLASS: Record<ModelCapability, string> = {
    vision: 'bg-purple-50 text-purple-700 border-purple-200',
    tools: 'bg-blue-50 text-blue-700 border-blue-200',
    json: 'bg-emerald-50 text-emerald-700 border-emerald-200',
    longContext: 'bg-amber-50 text-amber-700 border-amber-200',
    reasoning: 'bg-rose-50 text-rose-700 border-rose-200',
};

function CapabilityBadge({ cap }: { cap: ModelCapability }) {
    return (
        <span
            title={CAPABILITY_HINT[cap]}
            className={`inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium border ${CAP_BADGE_CLASS[cap]}`}
        >
            {CAPABILITY_LABEL[cap]}
        </span>
    );
}

function MissingBadge({ cap, severity }: { cap: ModelCapability; severity: 'required' | 'recommended' }) {
    const cls =
        severity === 'required'
            ? 'bg-red-50 text-red-700 border-red-200'
            : 'bg-amber-50 text-amber-700 border-amber-200';
    return (
        <span
            title={`${severity === 'required' ? 'Required' : 'Recommended'}: ${CAPABILITY_HINT[cap]}`}
            className={`inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium border line-through ${cls}`}
        >
            {CAPABILITY_LABEL[cap]}
        </span>
    );
}

function TagBadge({ tag }: { tag: string }) {
    return (
        <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-gray-100 text-gray-600 border border-gray-200">
            {tag}
        </span>
    );
}

function capList(caps: ModelCapability[]): string {
    return caps.map((c) => CAPABILITY_LABEL[c]).join(', ');
}

// ─── ModelInput: capability-aware picker popover ──────────────────────────────

export function ModelInput({
    value,
    onChange,
    models,
    highlighted,
    placeholder,
    taskKey,
}: {
    value: string;
    onChange: (v: string) => void;
    /** Either plain string IDs (legacy callers) or full ModelInfo records. */
    models: (string | ModelInfo)[];
    highlighted?: boolean;
    placeholder?: string;
    /** When provided, the picker filters to models that satisfy this task's capability requirements. */
    taskKey?: TaskKey;
}) {
    const [open, setOpen] = useState(false);
    const [query, setQuery] = useState('');
    const [showBlocked, setShowBlocked] = useState(false);
    const wrapRef = useRef<HTMLDivElement>(null);
    const triggerRef = useRef<HTMLButtonElement>(null);
    const popoverRef = useRef<HTMLDivElement>(null);
    const [pos, setPos] = useState<{ top: number; left: number; width: number; placeAbove: boolean } | null>(null);

    const allModels: ModelInfo[] = useMemo(
        () =>
            models.map((m) =>
                typeof m === 'string'
                    ? ({ id: m, provider: 'openai', description: '', capabilities: [] as ModelCapability[] } as ModelInfo)
                    : m,
            ),
        [models],
    );

    useEffect(() => {
        if (!open) return;
        const handler = (e: MouseEvent) => {
            const t = e.target as Node;
            if (wrapRef.current?.contains(t)) return;
            if (popoverRef.current?.contains(t)) return;
            setOpen(false);
        };
        const onKey = (e: KeyboardEvent) => {
            if (e.key === 'Escape') setOpen(false);
        };
        document.addEventListener('mousedown', handler);
        document.addEventListener('keydown', onKey);
        return () => {
            document.removeEventListener('mousedown', handler);
            document.removeEventListener('keydown', onKey);
        };
    }, [open]);

    useLayoutEffect(() => {
        if (!open) {
            setPos(null);
            return;
        }
        const compute = () => {
            const t = triggerRef.current;
            if (!t) return;
            const r = t.getBoundingClientRect();
            const vw = window.innerWidth;
            const vh = window.innerHeight;
            const desiredWidth = Math.min(460, Math.max(r.width, Math.floor(vw * 0.9)));
            const width = Math.min(desiredWidth, vw - 16);
            // Estimate popover height: search row + chips + list (max-h-80=20rem≈320) + footer ≈ 420 cap.
            const estHeight = 420;
            const spaceBelow = vh - r.bottom - 8;
            const spaceAbove = r.top - 8;
            const placeAbove = spaceBelow < Math.min(estHeight, 240) && spaceAbove > spaceBelow;
            const top = placeAbove
                ? Math.max(8, r.top - 4 - estHeight)
                : r.bottom + 4;
            // Right-align if trigger is near right edge so popover stays on screen.
            let left = r.left;
            if (left + width > vw - 8) left = Math.max(8, vw - width - 8);
            setPos({ top, left, width, placeAbove });
        };
        compute();
        const onScroll = () => compute();
        const onResize = () => compute();
        window.addEventListener('scroll', onScroll, true);
        window.addEventListener('resize', onResize);
        return () => {
            window.removeEventListener('scroll', onScroll, true);
            window.removeEventListener('resize', onResize);
        };
    }, [open]);

    const requirements = taskKey ? TASK_REQUIREMENTS[taskKey] : null;
    const hasRequirements = !!requirements && (requirements.required.length > 0 || requirements.recommended.length > 0);

    const evaluations = useMemo(() => {
        const map = new Map<string, ReturnType<typeof evaluateModelForTask>>();
        if (!taskKey) return map;
        for (const m of allModels) map.set(m.id, evaluateModelForTask(m, taskKey));
        return map;
    }, [allModels, taskKey]);

    const selected = allModels.find((m) => m.id === value);
    const selectedEval = selected && taskKey ? evaluateModelForTask(selected, taskKey) : null;

    const filtered = useMemo(() => {
        const q = query.trim().toLowerCase();
        return allModels.filter((m) => {
            if (q) {
                const hay = `${m.id} ${m.name ?? ''} ${m.description} ${(m.tags ?? []).join(' ')}`.toLowerCase();
                if (!hay.includes(q)) return false;
            }
            const evalRes = evaluations.get(m.id);
            if (!showBlocked && evalRes?.blocked) return false;
            return true;
        });
    }, [allModels, query, showBlocked, evaluations]);

    const blockedCount = useMemo(() => {
        if (!taskKey) return 0;
        let n = 0;
        for (const m of allModels) {
            if (evaluations.get(m.id)?.blocked) n += 1;
        }
        return n;
    }, [allModels, evaluations, taskKey]);

    const triggerClass = `w-full px-3 py-2 rounded-lg border text-sm font-mono focus:outline-none focus:ring-2 focus:ring-orange-300 focus:border-orange-400 transition-all placeholder:text-gray-300 cursor-pointer ${
        highlighted ? 'border-orange-300 bg-orange-50/40' : 'border-gray-200 bg-white'
    }`;

    return (
        <div className="relative" ref={wrapRef}>
            <button
                ref={triggerRef}
                type="button"
                onClick={() => setOpen((o) => !o)}
                className={`${triggerClass} text-left flex items-center gap-2`}
                title={
                    selected?.description ??
                    (value && taskKey ? 'Custom model — capabilities unknown' : undefined)
                }
            >
                <span className="flex-1 truncate">
                    {value || <span className="text-gray-300 font-sans">{placeholder ?? 'Select a model'}</span>}
                </span>
                {selectedEval?.blocked && (
                    <span
                        className="text-red-600 text-xs"
                        title={`Missing required: ${capList(selectedEval.missingRequired)}`}
                    >
                        ✕
                    </span>
                )}
                {!selectedEval?.blocked && selectedEval && selectedEval.missingRecommended.length > 0 && (
                    <span
                        className="text-amber-500 text-xs"
                        title={`Recommended but missing: ${capList(selectedEval.missingRecommended)}`}
                    >
                        ⚠
                    </span>
                )}
                <span className="text-gray-400 text-xs">▾</span>
            </button>

            {/* Below-trigger inline warning so users notice without hovering. */}
            {selectedEval?.blocked && (
                <div className="mt-1 text-[10px] text-red-600 leading-snug">
                    Not suitable for this task — missing required capability: <strong>{capList(selectedEval.missingRequired)}</strong>.
                </div>
            )}
            {!selectedEval?.blocked && selectedEval && selectedEval.missingRecommended.length > 0 && (
                <div className="mt-1 text-[10px] text-amber-700 leading-snug">
                    Works, but quality may suffer — missing recommended: <strong>{capList(selectedEval.missingRecommended)}</strong>.
                </div>
            )}

            {open && pos && createPortal(
                <div
                    ref={popoverRef}
                    style={{ position: 'fixed', top: pos.top, left: pos.left, width: pos.width, zIndex: 1000 }}
                    className="bg-white border border-gray-200 rounded-xl shadow-xl overflow-hidden"
                >
                    <div className="px-3 py-2 border-b border-gray-100 bg-gray-50/60 flex flex-col gap-2">
                        <input
                            autoFocus
                            type="text"
                            value={query}
                            onChange={(e) => setQuery(e.target.value)}
                            placeholder="Search by name, description, or tag…"
                            className="w-full px-2 py-1.5 rounded-md border border-gray-200 text-xs focus:outline-none focus:ring-2 focus:ring-orange-300 bg-white"
                        />
                        {hasRequirements && requirements && (
                            <div className="flex items-center gap-2 flex-wrap">
                                {requirements.required.length > 0 && (
                                    <>
                                        <span className="text-[10px] text-gray-500">Required:</span>
                                        {requirements.required.map((cap) => (
                                            <CapabilityBadge key={`r-${cap}`} cap={cap} />
                                        ))}
                                    </>
                                )}
                                {requirements.recommended.length > 0 && (
                                    <>
                                        <span className="text-[10px] text-gray-500 ml-1">Recommended:</span>
                                        {requirements.recommended.map((cap) => (
                                            <CapabilityBadge key={`p-${cap}`} cap={cap} />
                                        ))}
                                    </>
                                )}
                                {blockedCount > 0 && (
                                    <button
                                        type="button"
                                        onClick={() => setShowBlocked((s) => !s)}
                                        className="ml-auto text-[10px] text-orange-600 hover:text-orange-700 cursor-pointer"
                                    >
                                        {showBlocked
                                            ? 'Hide incompatible'
                                            : `Show all (${blockedCount} hidden)`}
                                    </button>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="max-h-80 overflow-y-auto py-1">
                        {filtered.length === 0 && (
                            <div className="px-3 py-6 text-center text-xs text-gray-400">
                                No models match.
                                {!showBlocked && blockedCount > 0 && (
                                    <>
                                        {' '}
                                        <button
                                            type="button"
                                            onClick={() => setShowBlocked(true)}
                                            className="text-orange-600 hover:text-orange-700 cursor-pointer underline"
                                        >
                                            Show all {blockedCount}
                                        </button>
                                    </>
                                )}
                            </div>
                        )}
                        {filtered.map((m) => {
                            const evalRes = evaluations.get(m.id);
                            const isSelected = m.id === value;
                            const blocked = evalRes?.blocked ?? false;
                            const hasWarn = !blocked && (evalRes?.missingRecommended.length ?? 0) > 0;
                            return (
                                <button
                                    key={m.id || '__default__'}
                                    type="button"
                                    disabled={blocked}
                                    onMouseDown={(e) => {
                                        if (blocked) {
                                            e.preventDefault();
                                            return;
                                        }
                                        e.preventDefault();
                                        onChange(m.id);
                                        setOpen(false);
                                        setQuery('');
                                    }}
                                    className={`w-full text-left px-3 py-2 transition-colors border-l-2 ${
                                        blocked
                                            ? 'opacity-50 cursor-not-allowed border-transparent bg-gray-50/40'
                                            : 'hover:bg-orange-50 cursor-pointer'
                                    } ${isSelected ? 'bg-orange-50 border-orange-400' : !blocked ? 'border-transparent' : ''}`}
                                    title={blocked ? `Disabled — missing required: ${capList(evalRes!.missingRequired)}` : undefined}
                                >
                                    <div className="flex items-center gap-2 mb-0.5">
                                        <span
                                            className={`font-mono text-xs ${
                                                isSelected ? 'text-orange-700 font-semibold' : 'text-gray-800'
                                            }`}
                                        >
                                            {m.id || '(CLI default)'}
                                        </span>
                                        {blocked && (
                                            <span className="text-red-600 text-[10px]" title="Required capability missing">
                                                ✕ blocked
                                            </span>
                                        )}
                                        {hasWarn && (
                                            <span className="text-amber-500 text-[10px]" title="Recommended capability missing">
                                                ⚠
                                            </span>
                                        )}
                                    </div>
                                    {m.description && (
                                        <div className="text-[11px] text-gray-500 leading-snug mb-1">{m.description}</div>
                                    )}
                                    <div className="flex flex-wrap gap-1">
                                        {m.capabilities.map((cap) => (
                                            <CapabilityBadge key={cap} cap={cap} />
                                        ))}
                                        {evalRes?.missingRequired.map((cap) => (
                                            <MissingBadge key={`mr-${cap}`} cap={cap} severity="required" />
                                        ))}
                                        {evalRes?.missingRecommended.map((cap) => (
                                            <MissingBadge key={`mp-${cap}`} cap={cap} severity="recommended" />
                                        ))}
                                        {(m.tags ?? []).map((t) => (
                                            <TagBadge key={t} tag={t} />
                                        ))}
                                    </div>
                                </button>
                            );
                        })}
                    </div>

                    <div className="px-3 py-1.5 border-t border-gray-100 bg-gray-50/60 text-[10px] text-gray-500">
                        Tip: only the selected model ID is saved to <span className="font-mono">config.json</span>.
                    </div>
                </div>,
                document.body,
            )}
        </div>
    );
}
