import { useState } from 'react';
import classnames from 'classnames';
import type { NetworkRequestSummary } from '../../../activator/types/state';

interface Props {
  req: NetworkRequestSummary;
}

const methodColors: Record<string, string> = {
  GET: 'bg-green-100 text-green-700',
  POST: 'bg-blue-100 text-blue-700',
  PUT: 'bg-yellow-100 text-yellow-700',
  PATCH: 'bg-orange-100 text-orange-700',
  DELETE: 'bg-red-100 text-red-700',
  HEAD: 'bg-gray-100 text-gray-600',
  OPTIONS: 'bg-gray-100 text-gray-600',
};

function methodBadgeClass(method: string): string {
  return methodColors[method.toUpperCase()] ?? 'bg-gray-100 text-gray-700';
}

function statusToneClasses(req: NetworkRequestSummary): { text: string; border: string; hover: string } {
  if (req.failed) return { text: 'text-red-600', border: 'border-l-red-400', hover: 'hover:bg-red-50/60' };
  const s = req.status ?? 0;
  if (s >= 500) return { text: 'text-red-600', border: 'border-l-red-400', hover: 'hover:bg-red-50/60' };
  if (s >= 400) return { text: 'text-orange-600', border: 'border-l-orange-400', hover: 'hover:bg-orange-50/60' };
  if (s >= 300) return { text: 'text-yellow-600', border: 'border-l-yellow-400', hover: 'hover:bg-yellow-50/60' };
  if (s >= 200) return { text: 'text-green-600', border: 'border-l-green-400', hover: 'hover:bg-green-50/60' };
  return { text: 'text-gray-400', border: 'border-l-gray-300', hover: 'hover:bg-gray-50' };
}

function pathOnly(url: string): { host: string; path: string } {
  try {
    const parsed = new URL(url);
    return { host: parsed.host, path: `${parsed.pathname}${parsed.search}` || '/' };
  } catch {
    return { host: '', path: url };
  }
}

function formatBody(body: unknown): string {
  if (body == null) return '';
  if (typeof body === 'string') return body;
  return JSON.stringify(body, null, 2);
}

function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

function bodySize(body: unknown): number {
  if (body == null) return 0;
  if (typeof body === 'string') return body.length;
  return JSON.stringify(body).length;
}

async function copyToClipboard(text: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    /* ignore — clipboard may be blocked in iframe */
  }
}

export default function NetworkRequestCard({ req }: Props) {
  const [expanded, setExpanded] = useState(false);
  const tone = statusToneClasses(req);
  const { host, path } = pathOnly(req.url);

  const hasReqBody = req.requestBody != null;
  const hasRespBody = req.responseBody != null;
  const hasReqHeaders = req.requestHeaders && Object.keys(req.requestHeaders).length > 0;
  const hasRespHeaders = req.responseHeaders && Object.keys(req.responseHeaders).length > 0;

  return (
    <div className={classnames('border-l-2 bg-white rounded-r-md transition-colors', tone.border, tone.hover)}>
      <div
        className="flex items-center gap-2 px-2 py-1.5 cursor-pointer"
        onClick={() => setExpanded((v) => !v)}
      >
        <span className={`shrink-0 px-1.5 py-px rounded text-[10px] font-bold ${methodBadgeClass(req.method)}`}>
          {req.method}
        </span>
        <span className={`shrink-0 text-[11px] font-semibold tabular-nums ${tone.text}`}>
          {req.failed ? 'FAIL' : req.status ?? '…'}
        </span>
        <span className="text-[12px] text-gray-700 font-mono truncate flex-1 min-w-0" title={req.url}>
          {path}
          {host && <span className="text-gray-400 ml-1">· {host}</span>}
        </span>
        {req.resourceType && req.resourceType !== 'other' && (
          <span className="hidden sm:inline shrink-0 text-[9px] text-gray-500 bg-gray-100 px-1 rounded uppercase tracking-wide">
            {req.resourceType}
          </span>
        )}
        {req.duration != null && (
          <span className="shrink-0 text-[10px] text-gray-400 tabular-nums">{req.duration}ms</span>
        )}
        <svg
          className={classnames('w-3 h-3 text-gray-400 shrink-0 transition-transform', expanded ? 'rotate-90' : '')}
          fill="currentColor"
          viewBox="0 0 20 20"
        >
          <path
            fillRule="evenodd"
            d="M7.21 5.23a.75.75 0 011.06-.02l3.85 4.25a.75.75 0 010 1.02l-3.85 4.25a.75.75 0 11-1.08-1.04l3.35-3.71-3.35-3.71a.75.75 0 01.02-1.06z"
            clipRule="evenodd"
          />
        </svg>
      </div>

      {req.failureReason && !expanded && (
        <div className="px-3 pb-1.5 -mt-1 text-[11px] text-red-600 truncate" title={req.failureReason}>
          {req.failureReason}
        </div>
      )}

      {expanded && (
        <div className="border-t border-gray-100 px-2.5 py-2 space-y-2.5">
          <Section
            label="URL"
            action={<CopyButton text={req.url} />}
          >
            <div className="text-[11px] text-gray-700 font-mono break-all bg-gray-50 rounded px-2 py-1.5 border border-gray-100">
              {req.url}
            </div>
          </Section>

          {req.failureReason && (
            <Section label="Failure">
              <div className="text-[11px] text-red-700 bg-red-50 border border-red-200 rounded px-2 py-1.5 break-all">
                {req.failureReason}
              </div>
            </Section>
          )}

          {hasReqHeaders && <HeaderTable label="Request Headers" headers={req.requestHeaders!} keyColor="text-blue-600" />}

          {hasReqBody && (
            <Section
              label={`Request Body · ${formatBytes(bodySize(req.requestBody))}`}
              action={<CopyButton text={formatBody(req.requestBody)} />}
            >
              <pre className="bg-gray-50 rounded px-2 py-1.5 text-[11px] font-mono whitespace-pre-wrap break-all max-h-48 overflow-auto text-gray-700 border border-gray-100">
                {formatBody(req.requestBody)}
              </pre>
            </Section>
          )}

          {hasRespHeaders && <HeaderTable label="Response Headers" headers={req.responseHeaders!} keyColor="text-purple-600" />}

          {hasRespBody && (
            <Section
              label={`Response Body · ${formatBytes(bodySize(req.responseBody))}`}
              action={<CopyButton text={formatBody(req.responseBody)} />}
            >
              <pre className="bg-gray-50 rounded px-2 py-1.5 text-[11px] font-mono whitespace-pre-wrap break-all max-h-64 overflow-auto text-gray-700 border border-gray-100">
                {formatBody(req.responseBody)}
              </pre>
            </Section>
          )}

          {!hasRespBody && !req.failed && (
            <p className="text-[10px] text-gray-400 italic">
              Response body not captured — only JSON responses are stored.
            </p>
          )}
        </div>
      )}
    </div>
  );
}

function Section({
  label,
  action,
  children,
}: {
  label: string;
  action?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <div>
      <div className="flex items-center justify-between mb-1">
        <h4 className="text-[10px] font-semibold text-gray-500 uppercase tracking-wide">{label}</h4>
        {action}
      </div>
      {children}
    </div>
  );
}

function HeaderTable({
  label,
  headers,
  keyColor,
}: {
  label: string;
  headers: Record<string, string>;
  keyColor: string;
}) {
  const entries = Object.entries(headers);
  return (
    <Section label={`${label} · ${entries.length}`}>
      <div className="bg-gray-50 rounded px-2 py-1.5 text-[11px] font-mono max-h-40 overflow-auto border border-gray-100">
        {entries.map(([key, val]) => (
          <div key={key} className="flex gap-1 leading-snug">
            <span className={`shrink-0 ${keyColor}`}>{key}:</span>
            <span className="text-gray-700 break-all min-w-0">{val}</span>
          </div>
        ))}
      </div>
    </Section>
  );
}

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      onClick={(e) => {
        e.stopPropagation();
        copyToClipboard(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 1200);
      }}
      className="text-[9px] uppercase tracking-wide text-gray-400 hover:text-gray-700 cursor-pointer"
    >
      {copied ? 'Copied' : 'Copy'}
    </button>
  );
}
