import { useEffect, useState } from 'react';

interface TaskBindingShape {
  provider: string;
  model: string;
}

interface ConfigShape {
  llm: {
    tasks: {
      default: Record<string, TaskBindingShape>;
      profiles: Record<string, Partial<Record<string, Partial<TaskBindingShape>>>>;
      activeProfile: string | null;
    };
  };
}

const PROVIDER_LABELS: Record<string, string> = {
  openai: 'OpenAI',
  bedrock: 'AWS Bedrock',
  bedrockapi: 'Bedrock API',
  'gh-copilot': 'GitHub Copilot',
  claudecode: 'Claude Code',
};

const PROVIDER_TONE: Record<string, string> = {
  openai: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  bedrock: 'bg-amber-50 text-amber-700 border-amber-200',
  bedrockapi: 'bg-amber-50 text-amber-700 border-amber-200',
  'gh-copilot': 'bg-violet-50 text-violet-700 border-violet-200',
  claudecode: 'bg-orange-50 text-orange-700 border-orange-200',
};

function resolveTaskBinding(cfg: ConfigShape, taskKey: string): TaskBindingShape | null {
  const tasks = cfg.llm?.tasks;
  if (!tasks) return null;
  const base = tasks.default?.[taskKey];
  if (!base) return null;
  const activeProfile = tasks.activeProfile;
  if (!activeProfile) return base;
  const overrides = tasks.profiles?.[activeProfile]?.[taskKey];
  if (!overrides) return base;
  return { ...base, ...overrides } as TaskBindingShape;
}

export default function ComparisonProviderBadge() {
  const [binding, setBinding] = useState<TaskBindingShape | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch('/api/config')
      .then((r) => r.json())
      .then((data: { config?: ConfigShape }) => {
        if (cancelled) return;
        if (!data.config) {
          setError('config unavailable');
          return;
        }
        const resolved = resolveTaskBinding(data.config, 'comparison');
        if (!resolved) {
          setError('comparison task not configured');
          return;
        }
        setBinding(resolved);
      })
      .catch(() => {
        if (!cancelled) setError('config fetch failed');
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (error) {
    return (
      <span className="inline-flex items-center gap-1 px-2 py-1 text-[11px] font-medium rounded-md border border-gray-200 bg-gray-50 text-gray-500">
        AI: unknown
      </span>
    );
  }

  if (!binding) {
    return (
      <span className="inline-flex items-center gap-1 px-2 py-1 text-[11px] font-medium rounded-md border border-gray-200 bg-gray-50 text-gray-400">
        AI: …
      </span>
    );
  }

  const label = PROVIDER_LABELS[binding.provider] ?? binding.provider;
  const tone = PROVIDER_TONE[binding.provider] ?? 'bg-gray-50 text-gray-700 border-gray-200';
  const modelSuffix = binding.model && binding.model.trim() ? ` · ${binding.model}` : '';
  const tooltip = `Comparison task uses ${label}${modelSuffix}. Change in Settings → Tasks.`;

  return (
    <span
      className={`inline-flex items-center gap-1 px-2 py-1 text-[11px] font-medium rounded-md border ${tone}`}
      title={tooltip}
    >
      <span className="opacity-60">AI:</span>
      <span>{label}</span>
      {binding.model && binding.model.trim() ? <span className="opacity-60">· {binding.model}</span> : null}
    </span>
  );
}
