import { FailedIcon, PendingIcon, RunningIcon, SuccessIcon } from '../../styles/Icons';

interface Props {
    status: string;
}

export default function RunStatusIcon({ status }: Props) {
    switch (status) {
        case 'passed':
            return <SuccessIcon className="text-green-500" />;
        case 'failed':
            return <FailedIcon className="text-red-500" />;
        case 'running':
            return <RunningIcon className="text-blue-500" />;
        default:
            return <PendingIcon className="text-gray-400" />;
    }
}
