import classnames from 'classnames';
import type { StepLogCounts } from './stepCounts';

interface Props {
  counts: StepLogCounts;
  size?: 'compact' | 'spread';
}

export default function LogCountBadges({ counts, size = 'compact' }: Props) {
  const hasAny =
    counts.networkCount > 0 ||
    counts.networkErrorCount > 0 ||
    counts.consoleErrorCount > 0 ||
    counts.consoleWarnCount > 0;

  if (!hasAny) return null;

  const baseClass = size === 'compact'
    ? 'shrink-0 px-1 py-0 rounded text-[9px] font-semibold tabular-nums'
    : 'shrink-0 px-1.5 py-0.5 rounded text-[10px] font-semibold tabular-nums';

  return (
    <div className={classnames('inline-flex items-center gap-1', size === 'compact' ? 'ml-1' : '')}>
      {counts.networkCount > 0 && (
        <span
          className={classnames(baseClass, 'bg-blue-100 text-blue-700')}
          title={`${counts.networkCount} network request${counts.networkCount === 1 ? '' : 's'}`}
        >
          {counts.networkCount}N
        </span>
      )}
      {counts.networkErrorCount > 0 && (
        <span
          className={classnames(baseClass, 'bg-orange-100 text-orange-700')}
          title={`${counts.networkErrorCount} network error${counts.networkErrorCount === 1 ? '' : 's'} (status ≥ 400 or failed)`}
        >
          {counts.networkErrorCount}NE
        </span>
      )}
      {counts.consoleErrorCount > 0 && (
        <span
          className={classnames(baseClass, 'bg-red-100 text-red-700')}
          title={`${counts.consoleErrorCount} console error${counts.consoleErrorCount === 1 ? '' : 's'}`}
        >
          {counts.consoleErrorCount}CE
        </span>
      )}
      {counts.consoleWarnCount > 0 && (
        <span
          className={classnames(baseClass, 'bg-yellow-100 text-yellow-700')}
          title={`${counts.consoleWarnCount} console warning${counts.consoleWarnCount === 1 ? '' : 's'}`}
        >
          {counts.consoleWarnCount}CW
        </span>
      )}
    </div>
  );
}
