import { useState } from 'react';
import { createPortal } from 'react-dom';

interface TokenEntry {
  purpose: string;
  model: string;
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  cost: number;
  calls: number;
}

interface TokenUsagePanelProps {
  entries: TokenEntry[];
  title?: string;
}

const COST_TOOLTIP_TITLE = 'Estimated cost';
const COST_TOOLTIP_BODY =
  'Computed from token counts at standard pay-as-you-go API rates. For CLI-based assistants billed on a fixed subscription (Claude Code, Kiro, GitHub Copilot), this figure does not reflect your actual spend — those plans bundle far larger token allowances, so real cost is typically much lower.';

function CostInfoTooltip() {
  const [pos, setPos] = useState<{ top: number; left: number } | null>(null);

  const show = (e: React.MouseEvent<HTMLSpanElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    setPos({ top: r.bottom + 6, left: r.right });
  };

  return (
    <span
      className="group relative inline-flex"
      onMouseEnter={show}
      onMouseLeave={() => setPos(null)}
    >
      <span className="flex items-center justify-center w-3 h-3 rounded-full bg-gray-200 text-gray-500 text-[8px] font-bold cursor-help leading-none">
        i
      </span>
      {pos &&
        createPortal(
          <div
            role="tooltip"
            style={{ top: pos.top, left: pos.left }}
            className="fixed z-50 w-64 -translate-x-full"
          >
            <div className="rounded-lg bg-gray-900 px-3 py-2 text-left text-[10px] font-normal leading-relaxed text-gray-100 shadow-xl ring-1 ring-black/10">
              <span className="mb-1 block text-[11px] font-semibold text-white">{COST_TOOLTIP_TITLE}</span>
              {COST_TOOLTIP_BODY}
            </div>
          </div>,
          document.body,
        )}
    </span>
  );
}

const PURPOSE_LABELS: Record<string, string> = {
  vision: 'Vision',
  testcase_generation: 'Test Case Generation',
  test_plan_generation: 'Test Plan Generation',
  feature_classification: 'Feature Classification',
  step_execution: 'Step Execution',
  comparison: 'Comparison',
  code_generation: 'Code Generation',
  documentation: 'Documentation',
  summary_report_generation: 'Summary Report',
  defect_drafting: 'Defect Drafting',
};

function formatTokens(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}K`;
  return String(n);
}

function formatCost(n: number): string {
  if (n === 0) return '-';
  if (n < 0.001) return `$${n.toFixed(6)}`;
  if (n < 0.01) return `$${n.toFixed(4)}`;
  return `$${n.toFixed(3)}`;
}

export default function TokenUsagePanel({ entries, title }: TokenUsagePanelProps) {
  if (entries.length === 0) return null;

  const hasCacheData = entries.some((e) => e.cacheReadTokens > 0 || e.cacheWriteTokens > 0);
  const showTotal = entries.length > 1;

  const totalInput = entries.reduce((s, e) => s + e.inputTokens, 0);
  const totalOutput = entries.reduce((s, e) => s + e.outputTokens, 0);
  const totalCacheRead = entries.reduce((s, e) => s + e.cacheReadTokens, 0);
  const totalCacheWrite = entries.reduce((s, e) => s + e.cacheWriteTokens, 0);
  const totalCost = entries.reduce((s, e) => s + e.cost, 0);

  return (
    <div className="bg-white rounded-lg border border-gray-200 shadow-sm overflow-hidden flex">
      {title && (
        <div
          className="shrink-0 flex items-center justify-center bg-linear-to-b from-amber-50 to-orange-100 border-r border-orange-200 px-1"
          title={title}
        >
          <span
            className="text-[8px] font-bold uppercase tracking-widest text-orange-700/80 whitespace-nowrap select-none py-1"
            style={{ writingMode: 'vertical-rl', transform: 'rotate(180deg)' }}
          >
            Tokens
          </span>
        </div>
      )}
      <div className="overflow-x-auto flex-1 min-w-0">
        <table className="w-full text-[11px]">
          <thead>
            <tr className="border-b border-gray-100 text-gray-500">
              <th className="text-left px-3 py-1 font-medium whitespace-nowrap">Purpose</th>
              <th className="text-left px-2 py-1 font-medium whitespace-nowrap">Model</th>
              <th className="text-right px-2 py-1 font-medium whitespace-nowrap">Input</th>
              <th className="text-right px-2 py-1 font-medium whitespace-nowrap">Output</th>
              {hasCacheData && (
                <>
                  <th className="text-right px-2 py-1 font-medium whitespace-nowrap">Cache Read</th>
                  <th className="text-right px-2 py-1 font-medium whitespace-nowrap">Cache Write</th>
                </>
              )}
              <th className="text-right px-2 py-1 font-medium whitespace-nowrap">Calls</th>
              <th className="text-right px-3 py-1 font-medium whitespace-nowrap">
                <span className="inline-flex items-center justify-end gap-1">
                  Cost
                  <CostInfoTooltip />
                </span>
              </th>
            </tr>
          </thead>
          <tbody>
            {entries.map((e, i) => (
              <tr key={i} className="border-b border-gray-50 hover:bg-gray-50 last:border-0">
                <td className="px-3 py-1 text-gray-700 whitespace-nowrap">{PURPOSE_LABELS[e.purpose] || e.purpose}</td>
                <td className="px-2 py-1 text-gray-500 font-mono text-[10px] whitespace-nowrap">{e.model}</td>
                <td className="px-2 py-1 text-right text-blue-600 whitespace-nowrap">{formatTokens(e.inputTokens)}</td>
                <td className="px-2 py-1 text-right text-purple-600 whitespace-nowrap">{formatTokens(e.outputTokens)}</td>
                {hasCacheData && (
                  <>
                    <td className="px-2 py-1 text-right text-teal-600 whitespace-nowrap">
                      {e.cacheReadTokens > 0 ? formatTokens(e.cacheReadTokens) : '-'}
                    </td>
                    <td className="px-2 py-1 text-right text-orange-500 whitespace-nowrap">
                      {e.cacheWriteTokens > 0 ? formatTokens(e.cacheWriteTokens) : '-'}
                    </td>
                  </>
                )}
                <td className="px-2 py-1 text-right text-gray-400 whitespace-nowrap">{e.calls}</td>
                <td className="px-3 py-1 text-right font-medium text-gray-700 whitespace-nowrap">{formatCost(e.cost)}</td>
              </tr>
            ))}
          </tbody>
          {showTotal && (
            <tfoot>
              <tr className="bg-gray-50 font-semibold text-gray-700 border-t border-gray-200">
                <td className="px-3 py-1 whitespace-nowrap" colSpan={2}>Total</td>
                <td className="px-2 py-1 text-right text-blue-600 whitespace-nowrap">{formatTokens(totalInput)}</td>
                <td className="px-2 py-1 text-right text-purple-600 whitespace-nowrap">{formatTokens(totalOutput)}</td>
                {hasCacheData && (
                  <>
                    <td className="px-2 py-1 text-right text-teal-600 whitespace-nowrap">{formatTokens(totalCacheRead)}</td>
                    <td className="px-2 py-1 text-right text-orange-500 whitespace-nowrap">{formatTokens(totalCacheWrite)}</td>
                  </>
                )}
                <td className="px-2 py-1 text-right text-gray-400 whitespace-nowrap">{entries.reduce((s, e) => s + e.calls, 0)}</td>
                <td className="px-3 py-1 text-right whitespace-nowrap">{formatCost(totalCost)}</td>
              </tr>
            </tfoot>
          )}
        </table>
      </div>
    </div>
  );
}
