import { detectImageInValue, stripImageFieldsForJson } from '../lib/imageDetection';

interface Props {
  value: unknown;
  className?: string;
  imageAlt?: string;
}

export default function ToolDataPreview({ value, className, imageAlt }: Props) {
  const direct = detectImageInValue(value);
  const remainder = direct ? remainderAfterImage(value) : value;
  const showRemainder =
    remainder !== undefined &&
    remainder !== null &&
    !(typeof remainder === 'object' && Object.keys(remainder).length === 0);

  const stripped = showRemainder ? stripImageFieldsForJson(remainder) : null;
  const text = showRemainder
    ? typeof stripped === 'string'
      ? stripped
      : JSON.stringify(stripped, null, 2)
    : null;

  return (
    <div className="space-y-2">
      {direct && (
        <img
          src={direct.src}
          alt={imageAlt ?? 'tool result image'}
          className="max-w-full rounded-lg border border-gray-200"
        />
      )}
      {text != null && (
        <pre className={className ?? 'text-xs font-mono whitespace-pre-wrap break-all text-gray-600'}>
          {text}
        </pre>
      )}
    </div>
  );
}

function remainderAfterImage(value: unknown): unknown {
  if (typeof value === 'string') return undefined;
  if (value == null || typeof value !== 'object') return value;

  const obj = value as Record<string, unknown>;
  const imageKeys = ['base64', 'image', 'imageBase64', 'screenshot'];
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    if (imageKeys.includes(k) && typeof v === 'string') continue;
    out[k] = v;
  }
  return out;
}
