import { useEffect, type FunctionComponent } from 'react';
import classnames from 'classnames';
import { useStore, type GlobalToast } from '../store/state';

const AUTO_DISMISS_MS = 5000;

const GlobalToasts: FunctionComponent = () => {
  const toasts = useStore((s) => s.toasts);
  const dismissToast = useStore((s) => s.dismissToast);

  if (toasts.length === 0) return null;

  return (
    <div className="fixed top-4 right-4 z-[9999] flex flex-col gap-2 max-w-sm pointer-events-none">
      {toasts.map((t) => (
        <ToastItem key={t.id} toast={t} onDismiss={dismissToast} />
      ))}
    </div>
  );
};

interface ToastItemProps {
  toast: GlobalToast;
  onDismiss: (id: number) => void;
}

const ToastItem: FunctionComponent<ToastItemProps> = ({ toast, onDismiss }) => {
  useEffect(() => {
    const timer = setTimeout(() => onDismiss(toast.id), AUTO_DISMISS_MS);
    return () => clearTimeout(timer);
  }, [toast.id, onDismiss]);

  const colorClass = classnames(
    'pointer-events-auto rounded shadow-lg px-4 py-3 text-sm border flex items-start gap-3',
    {
      'bg-red-50 border-red-300 text-red-900': toast.level === 'error',
      'bg-amber-50 border-amber-300 text-amber-900': toast.level === 'warn',
      'bg-blue-50 border-blue-300 text-blue-900': toast.level === 'info',
    },
  );

  return (
    <div className={colorClass} role="alert">
      <div className="flex-1 min-w-0">
        <p className="font-semibold leading-tight">{labelFor(toast.level)}</p>
        <p className="mt-0.5 break-words">{toast.message}</p>
      </div>
      <button
        type="button"
        onClick={() => onDismiss(toast.id)}
        className="text-current opacity-60 hover:opacity-100 cursor-pointer leading-none"
        aria-label="Dismiss"
      >
        ×
      </button>
    </div>
  );
};

function labelFor(level: GlobalToast['level']): string {
  switch (level) {
    case 'error':
      return 'Error';
    case 'warn':
      return 'Warning';
    case 'info':
      return 'Info';
  }
}

export default GlobalToasts;
