import { useState } from 'react';
import type { TestRun } from '../../../activator/types/state';
import RunStatusIcon from './RunStatusIcon';
import FailedTestsList from './FailedTestsList';

interface Props {
    run: TestRun;
    onOpen: (runId: string) => void;
    onDelete: (runId: string) => void;
    onDraftBug: (runId: string, testCaseId: string) => void;
}

export default function RunCard({ run, onOpen, onDelete, onDraftBug }: Props) {
    const [expanded, setExpanded] = useState(false);
    const [confirmingDelete, setConfirmingDelete] = useState(false);

    const passed = run.testCaseResults.filter((r) => r.status === 'passed').length;
    const failed = run.testCaseResults.filter((r) => r.status === 'failed').length;
    const total = run.testCaseResults.length;
    const duration = run.testCaseResults.reduce((sum, r) => sum + (r.executionTime || 0), 0);
    const hasFailed = failed > 0;
    const isActive = run.status === 'running';

    const handleDeleteClick = () => {
        if (confirmingDelete) {
            onDelete(run.id);
        } else {
            setConfirmingDelete(true);
        }
    };

    const handleCancelDelete = (e: React.MouseEvent) => {
        e.stopPropagation();
        setConfirmingDelete(false);
    };

    return (
        <div className="rounded-lg border border-gray-200 bg-white">
            <div className="p-3 flex items-center gap-3">
                <RunStatusIcon status={run.status} />
                <div
                    className="flex-1 min-w-0 cursor-pointer"
                    onClick={() => setExpanded((v) => !v)}
                >
                    <div className="flex items-center gap-2 flex-wrap">
                        <span className="text-sm font-medium text-gray-800">
                            {run.mode === 'replay' ? 'Replay' : 'AI Run'}
                        </span>
                        <span className="text-[11px] text-gray-400">{new Date(run.startedAt).toLocaleString()}</span>
                    </div>
                    <div className="flex items-center gap-3 text-[11px] mt-0.5">
                        <span className="text-gray-500">{total} tests</span>
                        {passed > 0 && <span className="text-green-600">{passed} passed</span>}
                        {failed > 0 && <span className="text-red-600">{failed} failed</span>}
                        {duration > 0 && <span className="text-gray-400">{(duration / 1000).toFixed(1)}s</span>}
                    </div>
                </div>

                <button
                    onClick={() => onOpen(run.id)}
                    className="px-2 py-1 text-[11px] font-semibold bg-white text-gray-700 border border-gray-200 rounded hover:bg-gray-50 cursor-pointer"
                >
                    Open
                </button>

                {hasFailed && (
                    <button
                        onClick={() => setExpanded((v) => !v)}
                        className="px-2 py-1 text-[11px] font-semibold bg-white text-gray-700 border border-gray-200 rounded hover:bg-gray-50 cursor-pointer"
                    >
                        {expanded ? 'Hide failures' : 'View failures'}
                    </button>
                )}

                {!isActive && (
                    confirmingDelete ? (
                        <div className="flex items-center gap-1">
                            <button
                                onClick={handleDeleteClick}
                                className="px-2 py-1 text-[11px] font-semibold text-white bg-red-600 border border-red-600 rounded hover:bg-red-700 cursor-pointer"
                            >
                                Confirm
                            </button>
                            <button
                                onClick={handleCancelDelete}
                                className="px-2 py-1 text-[11px] font-semibold text-gray-600 bg-white border border-gray-200 rounded hover:bg-gray-50 cursor-pointer"
                            >
                                Cancel
                            </button>
                        </div>
                    ) : (
                        <button
                            onClick={handleDeleteClick}
                            className="px-2 py-1 text-[11px] font-semibold text-red-600 bg-white border border-red-200 rounded hover:bg-red-50 cursor-pointer"
                            title="Delete this run and its recorded data"
                        >
                            Delete
                        </button>
                    )
                )}
            </div>

            {expanded && hasFailed && (
                <FailedTestsList results={run.testCaseResults} runId={run.id} onDraftBug={onDraftBug} />
            )}
        </div>
    );
}
