import { useMemo, useState } from 'react';
import type { TestFinding } from '../../../../activator/types/state';

export interface FindingsGroup {
  testCaseId: string;
  testCaseTitle: string;
  status: 'pending' | 'running' | 'passed' | 'failed' | 'paused' | 'skipped' | 'aborted';
  findings: TestFinding[];
}

interface ExecutionFindingsRailProps {
  groups: FindingsGroup[];
  /** When true renders a compact heading without the empty-state prompt */
  compact?: boolean;
}

const TYPE_COLORS = {
  fail:    { bar: 'bg-red-500',    badge: 'bg-red-500',    text: 'text-red-700',    card: 'bg-red-50 border-red-200',    icon: '✕', iconColor: 'text-red-500' },
  warning: { bar: 'bg-amber-400',  badge: 'bg-amber-500',  text: 'text-amber-700',  card: 'bg-amber-50 border-amber-200', icon: '!', iconColor: 'text-amber-500' },
  info:    { bar: 'bg-sky-400',    badge: 'bg-sky-500',    text: 'text-sky-700',    card: 'bg-sky-50 border-sky-200',    icon: 'i', iconColor: 'text-sky-500' },
  pass:    { bar: 'bg-green-500',  badge: 'bg-green-500',  text: 'text-green-700',  card: 'bg-green-50 border-green-200', icon: '✓', iconColor: 'text-green-500' },
} as const;

const STATUS_DOT: Record<string, string> = {
  passed:  'bg-green-500',
  failed:  'bg-red-500',
  running: 'bg-blue-500 animate-pulse',
  paused:  'bg-amber-400',
  skipped: 'bg-gray-300',
  pending: 'bg-gray-300',
  aborted: 'bg-gray-400',
};

const SEVERITY_ORDER: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3 };

function severityBadge(severity: string | undefined) {
  if (!severity) return null;
  const colors: Record<string, string> = {
    critical: 'bg-red-100 text-red-700 border border-red-200',
    high:     'bg-orange-100 text-orange-700 border border-orange-200',
    medium:   'bg-amber-100 text-amber-700 border border-amber-200',
    low:      'bg-gray-100 text-gray-500 border border-gray-200',
  };
  return (
    <span className={`px-1.5 py-0.5 rounded text-[9px] uppercase font-bold tracking-wide ${colors[severity] ?? colors.low}`}>
      {severity}
    </span>
  );
}

// Two lines at ~11px in a ~240px rail fit roughly 120 characters.
const TWO_LINE_CHAR_THRESHOLD = 120;

function FindingCard({ finding }: { finding: TestFinding }) {
  const [expanded, setExpanded] = useState(false);
  const tone = TYPE_COLORS[finding.type];
  const hasMore =
    finding.message.includes('\n') ||
    finding.message.length > TWO_LINE_CHAR_THRESHOLD;

  return (
    <div
      className={`relative rounded-lg border ${tone.card} overflow-hidden transition-shadow hover:shadow-sm`}
    >
      {/* left accent bar */}
      <div className={`absolute left-0 top-0 bottom-0 w-1 ${tone.bar} rounded-l-lg`} />

      <div className="pl-3 pr-2.5 py-2">
        <div className="flex items-start gap-2">
          {/* type icon */}
          <span className={`mt-0.5 shrink-0 w-4 h-4 rounded-full flex items-center justify-center text-[9px] font-black text-white ${tone.badge}`}>
            {tone.icon}
          </span>

          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5 flex-wrap">
              <span className={`text-[10px] font-bold uppercase tracking-wide ${tone.text}`}>
                {finding.type}
              </span>
              {finding.isBug && (
                <span className="px-1.5 py-0.5 rounded text-[9px] uppercase font-bold bg-red-100 text-red-700 border border-red-200 tracking-wide">
                  bug
                </span>
              )}
              {severityBadge(finding.severity)}
            </div>
            <p className={`text-[11px] mt-0.5 leading-snug text-gray-800 ${!expanded ? 'line-clamp-2' : ''}`}>
              {finding.message}
            </p>
            {hasMore && (
              <button
                onClick={() => setExpanded(v => !v)}
                className="mt-0.5 text-[10px] text-gray-400 hover:text-gray-600 cursor-pointer"
              >
                {expanded ? 'Show less ▲' : 'Show more ▼'}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function TestCaseSection({ group }: { group: FindingsGroup }) {
  const [collapsed, setCollapsed] = useState(false);
  const dot = STATUS_DOT[group.status] ?? STATUS_DOT.pending;

  const counts = useMemo(() => {
    const c = { fail: 0, warning: 0, pass: 0, info: 0 };
    for (const f of group.findings) c[f.type]++;
    return c;
  }, [group.findings]);

  const sortedFindings = useMemo(
    () => [...group.findings].sort((a, b) => {
      const typeOrder = { fail: 0, warning: 1, info: 2, pass: 3 };
      const typeDiff = typeOrder[a.type] - typeOrder[b.type];
      if (typeDiff !== 0) return typeDiff;
      const sevA = SEVERITY_ORDER[a.severity ?? ''] ?? 99;
      const sevB = SEVERITY_ORDER[b.severity ?? ''] ?? 99;
      return sevA - sevB;
    }),
    [group.findings],
  );

  const isRunning = group.status === 'running';

  return (
    <div className="relative">
      {/* section header */}
      <button
        onClick={() => setCollapsed(v => !v)}
        className="w-full flex items-center gap-2 px-2 py-1.5 rounded-lg hover:bg-gray-50 transition-colors cursor-pointer group text-left"
      >
        {/* status dot */}
        <span className={`shrink-0 w-2 h-2 rounded-full ${dot}`} />

        <span className="text-[11px] font-semibold text-gray-700 flex-1 truncate leading-tight">
          {group.testCaseTitle}
        </span>

        {/* summary chips */}
        <div className="flex items-center gap-1 shrink-0">
          {counts.fail > 0 && (
            <span className="px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-red-100 text-red-600">
              {counts.fail} ✕
            </span>
          )}
          {counts.warning > 0 && (
            <span className="px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-amber-100 text-amber-600">
              {counts.warning} !
            </span>
          )}
          {counts.pass > 0 && (
            <span className="px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-green-100 text-green-600">
              {counts.pass} ✓
            </span>
          )}
          {counts.info > 0 && (
            <span className="px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-sky-100 text-sky-600">
              {counts.info} i
            </span>
          )}
        </div>

        {/* chevron */}
        <span className="text-gray-300 group-hover:text-gray-400 text-[10px] ml-0.5 shrink-0">
          {collapsed ? '▶' : '▼'}
        </span>
      </button>

      {/* findings list */}
      {!collapsed && (
        <div className="mt-1 pl-3 space-y-1.5 pb-1">
          {group.findings.length === 0 && isRunning && (
            <div className="flex items-center gap-1.5 py-1.5">
              <div className="w-3 h-3 border-2 border-blue-300 border-t-blue-500 rounded-full animate-spin shrink-0" />
              <span className="text-[10px] text-gray-400 italic">Waiting for findings…</span>
            </div>
          )}
          {group.findings.length === 0 && !isRunning && (
            <p className="text-[10px] text-gray-400 italic py-1">No findings recorded.</p>
          )}
          {sortedFindings.map(f => (
            <FindingCard key={f.id} finding={f} />
          ))}
        </div>
      )}
    </div>
  );
}

export default function ExecutionFindingsRail({ groups, compact }: ExecutionFindingsRailProps) {
  const totalFindings = groups.reduce((s, g) => s + g.findings.length, 0);
  const failCount = groups.reduce((s, g) => s + g.findings.filter(f => f.type === 'fail').length, 0);
  const warnCount = groups.reduce((s, g) => s + g.findings.filter(f => f.type === 'warning').length, 0);
  const passCount = groups.reduce((s, g) => s + g.findings.filter(f => f.type === 'pass').length, 0);
  const activeGroups = groups.filter(g => g.findings.length > 0 || g.status === 'running' || g.status === 'paused');

  return (
    <div className="rounded-2xl border border-gray-200 bg-white flex flex-col h-full">
      {/* Rail header */}
      <div className="px-3.5 pt-3 pb-2.5 border-b border-gray-100">
        <div className="flex items-center justify-between gap-2">
          <h3 className="text-xs font-bold text-gray-800 tracking-tight">Findings</h3>
          {totalFindings > 0 && (
            <div className="flex items-center gap-1">
              {failCount > 0 && (
                <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-red-100 text-red-600">
                  {failCount} fail{failCount > 1 ? 's' : ''}
                </span>
              )}
              {warnCount > 0 && (
                <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-600">
                  {warnCount} warn{warnCount > 1 ? 's' : ''}
                </span>
              )}
              {passCount > 0 && (
                <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-green-100 text-green-600">
                  {passCount} pass
                </span>
              )}
            </div>
          )}
        </div>
        {!compact && totalFindings === 0 && activeGroups.length === 0 && (
          <p className="text-[10px] text-gray-400 mt-1">Findings will appear here as test cases run.</p>
        )}
        {totalFindings > 0 && (
          <p className="text-[10px] text-gray-400 mt-0.5">
            {totalFindings} finding{totalFindings !== 1 ? 's' : ''} across {activeGroups.length} test case{activeGroups.length !== 1 ? 's' : ''}
          </p>
        )}
      </div>

      {/* Scrollable content */}
      <div className="flex-1 overflow-y-auto px-2 py-2 space-y-1" style={{ minHeight: 0 }}>
        {activeGroups.length === 0 && (
          <div className="flex flex-col items-center justify-center py-10 text-center select-none">
            <span className="text-3xl mb-2 opacity-20">⚑</span>
            <p className="text-[11px] text-gray-400 font-medium">No findings yet</p>
            <p className="text-[10px] text-gray-300 mt-0.5">Results stream in as each test case runs</p>
          </div>
        )}

        {activeGroups.map((group, idx) => (
          <div key={group.testCaseId}>
            <TestCaseSection group={group} />
            {idx < activeGroups.length - 1 && (
              <div className="my-1.5 mx-2 h-px bg-linear-to-r from-transparent via-gray-200 to-transparent" />
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
