import { useMemo } from 'react';
import { useStore } from '../../store/state';
import type { ComparisonRun } from '../../../activator/types/comparisonPlan';
import type {
  ChartDiff,
  FormDiff,
  HoverScan,
  SectionDiff,
  StyleDiff,
  TableDiff,
  UnrenderedValue,
} from '../../../activator/engine/comparison/types';

interface Props {
  artifactKey: string;
  runId: string;
  sideLabels: { left: string; right: string };
  /**
   * When supplied, search this run's stored test-case steps for the diff
   * payload — used for historical runs where the live store has nothing.
   * For live runs leave undefined; the modal falls back to the live store.
   */
  runDetail?: ComparisonRun;
  onClose: () => void;
}

type AnyDiff = TableDiff | FormDiff | ChartDiff | SectionDiff | StyleDiff;

/**
 * Bottom-sheet modal showing the exact per-row / per-cell / per-header
 * differences for a given diff artifact. Lookup order:
 *   1. The live test-case store (during an in-flight run).
 *   2. The supplied `runDetail` (historical runs loaded from disk).
 * Falls back to a "diff data not found" hint with a download CTA.
 */
export default function ComparisonDiffDetailModal({ artifactKey, sideLabels, runDetail, onClose }: Props) {
  const testCasesByState = useStore((s) => s.comparisonTestCasesByState);

  const diff = useMemo<AnyDiff | null>(() => {
    // 1. Live store — present during an active run.
    for (const list of Object.values(testCasesByState)) {
      for (const tc of list) {
        for (const step of tc.steps) {
          if (!step.toolName.startsWith('compare_')) continue;
          if ((step.toolArgs as { diffArtifactKey?: string }).diffArtifactKey !== artifactKey) continue;
          const data = unwrapResult(step.result);
          if (data && typeof data === 'object' && 'kind' in data) return data as AnyDiff;
        }
      }
    }
    // 2. Historical run — same shape, just persisted to run.json on disk.
    if (runDetail) {
      for (const sr of runDetail.stateResults) {
        for (const tc of sr.testCases ?? []) {
          for (const step of tc.steps ?? []) {
            if (!step.toolName.startsWith('compare_')) continue;
            if ((step.toolArgs as { diffArtifactKey?: string }).diffArtifactKey !== artifactKey) continue;
            const data = unwrapResult(step.result);
            if (data && typeof data === 'object' && 'kind' in data) return data as AnyDiff;
          }
        }
      }
    }
    return null;
  }, [testCasesByState, runDetail, artifactKey]);

  const handleBackdrop = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget) onClose();
  };

  return (
    <div className="fixed inset-0 bg-[rgba(0,0,0,0.5)] flex items-end z-50" onClick={handleBackdrop}>
      <div className="bg-white rounded-t-2xl shadow-xl w-full min-h-[55vh] max-h-[85vh] overflow-hidden flex flex-col">
        <div className="sticky top-0 bg-white border-b border-gray-200 px-4 py-3 shrink-0">
          <div className="w-12 h-1 bg-gray-300 rounded-full mx-auto mb-2" />
          <div className="flex items-center justify-between gap-2">
            <div className="flex items-center gap-2 min-w-0">
              <h2 className="text-sm font-semibold text-gray-800 truncate">
                Diff — <span className="font-mono text-xs">{artifactKey}</span>
              </h2>
              {diff && (
                <span
                  className={`px-1.5 py-0.5 rounded text-[10px] uppercase font-semibold text-white ${
                    diff.verdict === 'match' ? 'bg-green-600' : 'bg-red-600'
                  }`}
                >
                  {diff.verdict}
                </span>
              )}
            </div>
            <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1 cursor-pointer shrink-0">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 text-sm">
          {!diff && (
            <p className="text-gray-500">
              Diff data not found in the live run. This happens when the comparison was produced in an earlier run —
              download the Markdown report from the Diffs panel to see the full breakdown.
            </p>
          )}
          {diff?.kind === 'table_diff' && <TableDiffBody diff={diff} labels={sideLabels} />}
          {diff?.kind === 'form_diff' && <FormDiffBody diff={diff} labels={sideLabels} />}
          {diff?.kind === 'chart_diff' && <ChartDiffBody diff={diff} labels={sideLabels} />}
          {diff?.kind === 'section_diff' && <SectionDiffBody diff={diff} labels={sideLabels} />}
          {diff?.kind === 'style_diff' && <StyleDiffBody diff={diff} labels={sideLabels} />}
        </div>
      </div>
    </div>
  );
}

const UNRENDERED_KIND_LABEL: Record<UnrenderedValue['kind'], string> = {
  object: 'an object was bound instead of text',
  undefined: '"undefined" was assigned as text',
  null: '"null" was assigned as text',
  nan: '"NaN" was assigned as text',
};

function UnrenderedValuesSection({
  values,
  labels,
}: {
  values: UnrenderedValue[];
  labels: { left: string; right: string };
}) {
  return (
    <Section title="Unrendered values — broken bindings (not compared)">
      <p className="text-[11px] text-gray-600 mb-1">
        These values were not real text — the page bound a non-value (object / undefined / null) where a string was
        expected, so they are reported as defects instead of being compared.
      </p>
      {values.map((v, i) => {
        const sideText =
          v.side === 'both'
            ? `${labels.left} & ${labels.right}`
            : v.side === 'left'
              ? labels.left
              : labels.right;
        const shown = v.rightValue ?? v.leftValue ?? '';
        return (
          <p key={i} className="text-[11px]">
            <span className="font-semibold">{v.location}</span> — {UNRENDERED_KIND_LABEL[v.kind]} on{' '}
            <b>{sideText}</b>
            {shown && (
              <>
                {' '}
                (<span className="font-mono text-red-700">{shown}</span>)
              </>
            )}
          </p>
        );
      })}
    </Section>
  );
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div>
      <h3 className="text-xs font-semibold text-gray-500 uppercase mb-2">{title}</h3>
      <div className="rounded-lg border border-gray-200 bg-gray-50/60 p-3 space-y-1">{children}</div>
    </div>
  );
}

function unwrapResult(result: unknown): unknown {
  if (!result || typeof result !== 'object') return result;
  const r = result as { success?: unknown; data?: unknown };
  if ('data' in r) return r.data;
  return result;
}

function TableDiffBody({ diff, labels }: { diff: TableDiff; labels: { left: string; right: string } }) {
  // `columnHeaders` is populated by the comparator at compare time. When
  // a column has a real header label we render it; when the header text
  // was empty (icon-only `<th>` with no aria-label / title / alt to fall
  // back on), the resolver returns the canonical key flagged synthetic
  // and the cell renders italic to signal "not a real name."
  const columnRender = (canonical: string) => renderColumnLabel(diff, canonical);
  const groupedRowDiffs = useMemo(() => groupRowsByDiffSignature(diff.rowDiffs), [diff.rowDiffs]);
  return (
    <>
      {diff.unrenderedValues && diff.unrenderedValues.length > 0 && (
        <UnrenderedValuesSection values={diff.unrenderedValues} labels={labels} />
      )}

      {diff.titleMismatch && (
        <Section title="Title">
          <p>
            <b>{labels.left}:</b> "{diff.titleMismatch.left}"
          </p>
          <p>
            <b>{labels.right}:</b> "{diff.titleMismatch.right}"
          </p>
        </Section>
      )}

      {diff.headerMismatches.length > 0 && (
        <Section title="Header differences">
          {diff.headerMismatches.map((h, i) => (
            <p key={i}>
              <span className="font-semibold">{columnRender(h.canonical)}:</span> "{h.leftRaw || '(empty)'}" ({labels.left}) vs "
              {h.rightRaw || '(empty)'}" ({labels.right})
            </p>
          ))}
        </Section>
      )}

      {(diff.missingColumnsOnLeft.length > 0 || diff.missingColumnsOnRight.length > 0) && (
        <Section title="Missing columns">
          {diff.missingColumnsOnLeft.length > 0 && (
            <p>
              Missing on <b>{labels.left}:</b>{' '}
              {joinNodes(diff.missingColumnsOnLeft.map(columnRender), ', ')}
            </p>
          )}
          {diff.missingColumnsOnRight.length > 0 && (
            <p>
              Missing on <b>{labels.right}:</b>{' '}
              {joinNodes(diff.missingColumnsOnRight.map(columnRender), ', ')}
            </p>
          )}
        </Section>
      )}

      {diff.rowCountMismatch && (
        <Section title="Row counts">
          <p>
            <b>{labels.left}:</b> {diff.rowCountMismatch.left} rows — <b>{labels.right}:</b> {diff.rowCountMismatch.right} rows
          </p>
        </Section>
      )}

      {(diff.extraRowsOnLeftDetail?.length || diff.extraRowsOnRightDetail?.length) && (
        <Section title="Extra rows — content">
          {diff.extraRowsOnLeftDetail && diff.extraRowsOnLeftDetail.length > 0 && (
            <ExtraRowsTable label={labels.left} rows={diff.extraRowsOnLeftDetail} columnRender={columnRender} />
          )}
          {diff.extraRowsOnRightDetail && diff.extraRowsOnRightDetail.length > 0 && (
            <ExtraRowsTable label={labels.right} rows={diff.extraRowsOnRightDetail} columnRender={columnRender} />
          )}
        </Section>
      )}

      {groupedRowDiffs.length > 0 && (
        <Section title={`Rows with differences (${diff.rowDiffs.length} ${diff.rowDiffs.length === 1 ? 'row' : 'rows'} — ${groupedRowDiffs.length} distinct pattern${groupedRowDiffs.length === 1 ? '' : 's'})`}>
          <GroupedRowDiffs groups={groupedRowDiffs} labels={labels} columnRender={columnRender} />
        </Section>
      )}

      {diff.interactiveNotice && diff.interactiveNotice.needsBehaviorCheck > 0 && (
        <Section title="Interactive elements needing validation">
          <p className="text-[11px] text-gray-600 mb-1">
            {diff.interactiveNotice.needsBehaviorCheck} of {diff.interactiveNotice.total} interactive element(s) have no static target to diff (click-handler driven) — validate their behaviour manually.
          </p>
          {diff.interactiveNotice.samples.map((s, i) => (
            <p key={i} className="text-[11px]">
              row #{s.rowIndex + 1}, {columnRender(s.column)}: {s.kind}{s.label ? ` "${s.label}"` : ''} — {s.reason}
            </p>
          ))}
        </Section>
      )}

      {diff.hoverNotice && (
        <Section title="Hover / tooltip elements (hover-probe to validate)">
          <HoverScanLine label={labels.left} scan={diff.hoverNotice.left} />
          <HoverScanLine label={labels.right} scan={diff.hoverNotice.right} />
        </Section>
      )}
    </>
  );
}

function HoverScanLine({ label, scan }: { label: string; scan: HoverScan }) {
  const bits: string[] = [];
  if (scan.region) bits.push(`in ${scan.region}`);
  if (scan.staticTooltips > 0) bits.push(`${scan.staticTooltips} tooltip(s)`);
  if (scan.hoverHandlers > 0) bits.push(`${scan.hoverHandlers} hover handler(s)`);
  if (scan.tooltipClasses.length > 0) bits.push(`classes: ${scan.tooltipClasses.join(', ')}`);
  if (bits.length === 0) return null;
  return (
    <p className="text-[11px]">
      <b>{label}:</b> {bits.join(', ')}
      {scan.sampleTips.length > 0 && <span className="text-gray-500"> — e.g. "{scan.sampleTips[0]}"</span>}
    </p>
  );
}

/**
 * Render a canonical column key as a React node — plain text when a real
 * header label was captured, italic gray text when we only have the
 * synthetic `column_<N>` fallback. The italic styling is a visual signal
 * to the user that this column had no real header text in the source DOM
 * (icon-only `<th>` with no aria-label / title / alt fallback either),
 * so they don't mistake `column_3` for a real column name.
 */
function renderColumnLabel(diff: TableDiff, canonical: string): React.ReactNode {
  const headers = diff.columnHeaders?.[canonical];
  const left = headers?.leftRaw?.trim();
  const right = headers?.rightRaw?.trim();
  if (left && right && left === right) return left;
  if (left && right) return `${left} / ${right}`;
  if (left || right) return left || right;
  return <span className="italic text-gray-500" title="No header text was captured for this column">{canonical}</span>;
}

/**
 * Join an array of React nodes with a separator string. Plain `Array.join`
 * stringifies nodes; we want to keep them as JSX so italic styling on
 * synthetic column labels survives.
 */
function joinNodes(nodes: React.ReactNode[], sep: string): React.ReactNode {
  return nodes.flatMap((n, i) => (i === 0 ? [n] : [sep, n]));
}

/**
 * Build a stable signature describing one row's diff payload — same
 * signature means same set of (column, kind, leftValue, rightValue)
 * tuples. Used to collapse N rows with identical diffs into one block.
 *
 * Style differences alone are common across hundreds of rows (whole-table
 * font / colour rebrands), and showing them per-row drowns the table.
 * Including style props in the signature is fine because the user wants
 * to see the visual difference once, not 1000 times.
 */
function rowDiffSignature(row: TableDiff['rowDiffs'][number]): string {
  const parts: string[] = [];
  for (const c of row.cells) {
    const fields: Array<[string, { left?: string | null; right?: string | null } | undefined]> = [
      ['v', c.visibleMismatch],
      ['h', c.hiddenMismatch],
      ['a', c.ariaMismatch],
      ['t', c.titleMismatch],
      ['l', c.altMismatch],
    ];
    for (const [tag, fm] of fields) {
      if (!fm) continue;
      parts.push(`${tag}|${c.column}|${fm.left ?? ''}|${fm.right ?? ''}`);
    }
    if (c.styleMismatch) {
      const styleKeys = Object.keys(c.styleMismatch).sort();
      for (const k of styleKeys) {
        const sm = (c.styleMismatch as Record<string, { left?: string; right?: string } | undefined>)[k];
        if (!sm) continue;
        parts.push(`s|${c.column}|${k}|${sm.left ?? ''}|${sm.right ?? ''}`);
      }
    }
    if (c.interactiveMismatch) {
      for (const ch of c.interactiveMismatch.changes) {
        parts.push(`i|${c.column}|${ch.index}|${ch.onlyOn ?? ''}|${ch.leftDesc ?? ''}|${ch.rightDesc ?? ''}`);
      }
    }
  }
  for (const dec of row.decorations ?? []) {
    parts.push(`d|${dec.column}|L:${(dec.missingOnLeft ?? []).join(',')}|R:${(dec.missingOnRight ?? []).join(',')}`);
  }
  parts.sort();
  return parts.join('||');
}

interface RowDiffGroup {
  signature: string;
  rows: TableDiff['rowDiffs'];
  template: TableDiff['rowDiffs'][number];
}

/**
 * Group rows whose diff signatures match. Adjacent or non-adjacent rows
 * with the same signature collapse into the same group — the user wants
 * "rows #1–#100 all have these style differences" not 100 identical
 * tables. Each group keeps a representative `template` row whose payload
 * the renderer uses, and the full row index list for compact display.
 */
function groupRowsByDiffSignature(rows: TableDiff['rowDiffs']): RowDiffGroup[] {
  const map = new Map<string, RowDiffGroup>();
  const order: string[] = [];
  for (const r of rows) {
    const sig = rowDiffSignature(r);
    let group = map.get(sig);
    if (!group) {
      group = { signature: sig, rows: [], template: r };
      map.set(sig, group);
      order.push(sig);
    }
    group.rows.push(r);
  }
  return order.map((sig) => map.get(sig)!);
}

/** Compress a sorted index list into ranges: [0,1,2,5,7,8] → "#1–#3, #6, #8–#9". */
function formatRowRanges(rows: TableDiff['rowDiffs']): string {
  if (rows.length === 0) return '';
  const indexes = rows.map((r) => r.index).sort((a, b) => a - b);
  const ranges: string[] = [];
  let start = indexes[0];
  let prev = indexes[0];
  for (let i = 1; i < indexes.length; i++) {
    const cur = indexes[i];
    if (cur === prev + 1) {
      prev = cur;
      continue;
    }
    ranges.push(start === prev ? `#${start + 1}` : `#${start + 1}–#${prev + 1}`);
    start = cur;
    prev = cur;
  }
  ranges.push(start === prev ? `#${start + 1}` : `#${start + 1}–#${prev + 1}`);
  return ranges.join(', ');
}

function formatSources(list?: string[]): string {
  if (!list || list.length === 0) return '';
  return ` [from: ${list.join(', ')}]`;
}

/**
 * Render the row diffs as a sequence of "diff blocks" — one block per
 * unique signature. Each block shows the differences once and lists the
 * row range(s) the block applies to. This collapses the most common
 * pathology in the old UI: 1000 rows with the same row of style diffs
 * displayed identically 1000 times.
 */
function GroupedRowDiffs({
  groups,
  labels,
  columnRender,
}: {
  groups: RowDiffGroup[];
  labels: { left: string; right: string };
  columnRender: (canonical: string) => React.ReactNode;
}) {
  return (
    <div className="space-y-3">
      {groups.map((g, gi) => (
        <DiffGroupBlock key={g.signature || gi} group={g} labels={labels} columnRender={columnRender} />
      ))}
    </div>
  );
}

function DiffGroupBlock({
  group,
  labels,
  columnRender,
}: {
  group: RowDiffGroup;
  labels: { left: string; right: string };
  columnRender: (canonical: string) => React.ReactNode;
}) {
  const { template, rows } = group;
  // Single-row group → just say "Row #N". Multi-row → show ranges.
  const heading = rows.length === 1
    ? `Row ${template.keyLabel || `#${template.index + 1}`}`
    : `Rows ${formatRowRanges(rows)} (${rows.length} rows — same differences)`;

  const entries: Array<{ key: string; column: string; kind: string; left: string; right: string }> = [];
  for (const c of template.cells) {
    if (c.visibleMismatch) entries.push({
      key: `v-${c.column}`, column: c.column, kind: 'visible text',
      left: `${c.visibleMismatch.left}${formatSources(c.visibleMismatch.leftSources)}`,
      right: `${c.visibleMismatch.right}${formatSources(c.visibleMismatch.rightSources)}`,
    });
    if (c.hiddenMismatch) entries.push({
      key: `h-${c.column}`, column: c.column, kind: 'hidden text',
      left: `${c.hiddenMismatch.left}${formatSources(c.hiddenMismatch.leftSources)}`,
      right: `${c.hiddenMismatch.right}${formatSources(c.hiddenMismatch.rightSources)}`,
    });
    if (c.ariaMismatch) entries.push({
      key: `a-${c.column}`, column: c.column, kind: 'aria-label',
      left: `${c.ariaMismatch.left}${formatSources(c.ariaMismatch.leftSources)}`,
      right: `${c.ariaMismatch.right}${formatSources(c.ariaMismatch.rightSources)}`,
    });
    if (c.titleMismatch) entries.push({
      key: `t-${c.column}`, column: c.column, kind: 'title',
      left: c.titleMismatch.left, right: c.titleMismatch.right,
    });
    if (c.altMismatch) entries.push({
      key: `l-${c.column}`, column: c.column, kind: 'alt',
      left: c.altMismatch.left, right: c.altMismatch.right,
    });
    if (c.styleMismatch) {
      for (const [prop, sm] of Object.entries(c.styleMismatch)) {
        if (!sm) continue;
        entries.push({
          key: `s-${c.column}-${prop}`, column: c.column, kind: `style: ${prop}`,
          left: sm.left ?? '', right: sm.right ?? '',
        });
      }
    }
    if (c.interactiveMismatch) {
      for (const ch of c.interactiveMismatch.changes) {
        if (ch.onlyOn) {
          entries.push({
            key: `i-${c.column}-${ch.index}`, column: c.column, kind: `${ch.kind} (only on ${ch.onlyOn})`,
            left: ch.onlyOn === 'left' ? ch.leftDesc ?? '' : '(absent)',
            right: ch.onlyOn === 'right' ? ch.rightDesc ?? '' : '(absent)',
          });
        } else {
          const attrLabel = (ch.attrs ?? []).map((a) => a.attr).join(', ');
          entries.push({
            key: `i-${c.column}-${ch.index}`, column: c.column, kind: `${ch.kind}${attrLabel ? ` (${attrLabel})` : ''}`,
            left: ch.leftDesc ?? '', right: ch.rightDesc ?? '',
          });
        }
      }
    }
  }
  for (const dec of template.decorations ?? []) {
    if (dec.missingOnLeft?.length) entries.push({
      key: `dl-${dec.column}`, column: dec.column, kind: 'decoration',
      left: 'missing', right: dec.missingOnLeft.join(', '),
    });
    if (dec.missingOnRight?.length) entries.push({
      key: `dr-${dec.column}`, column: dec.column, kind: 'decoration',
      left: dec.missingOnRight.join(', '), right: 'missing',
    });
  }

  return (
    <div className="border border-gray-200 rounded bg-white">
      <div className="px-2 py-1.5 bg-gray-50 border-b border-gray-200 text-[11px] font-semibold text-gray-700">
        {heading}
      </div>
      <table className="w-full text-xs border-collapse">
        <thead>
          <tr className="bg-gray-50 text-left">
            <th className="p-1.5 border-b border-gray-200">Column</th>
            <th className="p-1.5 border-b border-gray-200">Kind</th>
            <th className="p-1.5 border-b border-gray-200">{labels.left}</th>
            <th className="p-1.5 border-b border-gray-200">{labels.right}</th>
          </tr>
        </thead>
        <tbody>
          {entries.map((e) => (
            <tr key={e.key}>
              <td className="p-1.5 border-b border-gray-100">{columnRender(e.column)}</td>
              <td className="p-1.5 border-b border-gray-100 text-gray-600">{e.kind}</td>
              <td className="p-1.5 border-b border-gray-100 text-red-700">{e.left}</td>
              <td className="p-1.5 border-b border-gray-100 text-red-700">{e.right}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function ExtraRowsTable({
  label,
  rows,
  columnRender,
}: {
  label: string;
  rows: NonNullable<TableDiff['extraRowsOnLeftDetail']>;
  columnRender: (canonical: string) => React.ReactNode;
}) {
  // Build a column list from the union of keys across the rows, preserving first-seen order.
  const columns: string[] = [];
  const seen = new Set<string>();
  for (const r of rows) {
    for (const k of Object.keys(r.cells)) {
      if (!seen.has(k)) { seen.add(k); columns.push(k); }
    }
  }
  return (
    <div>
      <p className="text-[11px] text-gray-600 mb-1">
        <b>{label}</b> has {rows.length} row(s) not present on the other side:
      </p>
      <div className="overflow-x-auto">
        <table className="w-full text-xs border-collapse">
          <thead>
            <tr className="bg-gray-100 text-left">
              <th className="p-1.5 border border-gray-200">Row</th>
              {columns.map((c) => (<th key={c} className="p-1.5 border border-gray-200">{columnRender(c)}</th>))}
            </tr>
          </thead>
          <tbody>
            {rows.slice(0, 100).map((r, i) => (
              <tr key={i}>
                <td className="p-1.5 border border-gray-200 font-mono">{r.keyLabel || `#${r.index + 1}`}</td>
                {columns.map((c) => (<td key={c} className="p-1.5 border border-gray-200">{r.cells[c] ?? ''}</td>))}
              </tr>
            ))}
          </tbody>
        </table>
        {rows.length > 100 && (
          <p className="mt-2 text-[11px] text-gray-500">…and {rows.length - 100} more rows. Download the Markdown report for the full list.</p>
        )}
      </div>
    </div>
  );
}

function FormDiffBody({ diff, labels }: { diff: FormDiff; labels: { left: string; right: string } }) {
  return (
    <>
      {diff.unrenderedValues && diff.unrenderedValues.length > 0 && (
        <UnrenderedValuesSection values={diff.unrenderedValues} labels={labels} />
      )}
      {diff.titleMismatch && (
        <Section title="Title">
          <p><b>{labels.left}:</b> "{diff.titleMismatch.left}"</p>
          <p><b>{labels.right}:</b> "{diff.titleMismatch.right}"</p>
        </Section>
      )}
      {diff.tabMismatches.length > 0 && (
        <Section title="Tab labels">
          {diff.tabMismatches.map((t, i) => (<p key={i}>{t}</p>))}
        </Section>
      )}
      {(diff.missingFieldsOnLeft.length > 0 || diff.missingFieldsOnRight.length > 0) && (
        <Section title="Missing fields">
          {diff.missingFieldsOnLeft.length > 0 && <p>Missing on <b>{labels.left}:</b> {diff.missingFieldsOnLeft.join(', ')}</p>}
          {diff.missingFieldsOnRight.length > 0 && <p>Missing on <b>{labels.right}:</b> {diff.missingFieldsOnRight.join(', ')}</p>}
        </Section>
      )}
      {diff.fieldDiffs.length > 0 && (
        <Section title={`Field differences (${diff.fieldDiffs.length})`}>
          {diff.fieldDiffs.map((f, i) => (
            <div key={i} className="border border-gray-200 rounded p-2 bg-white">
              <p className="font-semibold text-gray-700">{f.canonical}</p>
              {f.labelMismatch && <p className="mt-1">label: "{f.labelMismatch.left}" ({labels.left}) ≠ "{f.labelMismatch.right}" ({labels.right})</p>}
              {f.valueMismatch && <p className="mt-1">value: "{f.valueMismatch.left}" ({labels.left}) ≠ "{f.valueMismatch.right}" ({labels.right})</p>}
              {f.typeMismatch && <p className="mt-1">type: {f.typeMismatch.left} ({labels.left}) ≠ {f.typeMismatch.right} ({labels.right})</p>}
              {f.requiredMismatch && <p className="mt-1">required: {String(f.requiredMismatch.left)} ({labels.left}) ≠ {String(f.requiredMismatch.right)} ({labels.right})</p>}
              {f.helpTextMismatch && <p className="mt-1">help text differs</p>}
            </div>
          ))}
        </Section>
      )}
    </>
  );
}

function ChartDiffBody({ diff, labels }: { diff: ChartDiff; labels: { left: string; right: string } }) {
  // Detect "axis labels relabeled, values unchanged" per series. When the
  // y-value sequence matches in series order on both sides but the x
  // labels differ (the example from the user: old x=18..35 new x=2032..),
  // the user wants ONE axis-relabel notice instead of N spurious
  // "missing point" entries from pointDiffs.
  const axisRelabels = useMemo(() => detectAxisRelabels(diff), [diff]);
  const axisRelabelSeriesNames = new Set(axisRelabels.map((r) => r.series));

  // Filter out pointDiffs that are part of an axis-relabel — they're the
  // pseudo-mismatches caused purely by x-label drift.
  const filteredPointDiffs = diff.pointDiffs.filter((p) => !axisRelabelSeriesNames.has(p.series));

  return (
    <>
      {diff.unrenderedValues && diff.unrenderedValues.length > 0 && (
        <UnrenderedValuesSection values={diff.unrenderedValues} labels={labels} />
      )}
      {(diff.leftScreenshotBase64 || diff.rightScreenshotBase64) && (
        <Section title="Charts">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <ChartShot label={labels.left} base64={diff.leftScreenshotBase64} />
            <ChartShot label={labels.right} base64={diff.rightScreenshotBase64} />
          </div>
        </Section>
      )}

      {diff.seriesMismatches.length > 0 && (
        <Section title="Series">
          {diff.seriesMismatches.map((s, i) => (<p key={i}>{s}</p>))}
        </Section>
      )}

      {axisRelabels.length > 0 && (
        <Section title="Axis labels relabeled (values unchanged)">
          {axisRelabels.map((r) => (
            <div key={r.series} className="space-y-1">
              <p className="font-semibold">{r.series}</p>
              <p className="text-[11px] text-gray-600">
                Plotted values match in order; only the x-axis labels differ.
              </p>
              <p className="text-[11px]">
                <b>{labels.left}:</b> {r.leftRange}
              </p>
              <p className="text-[11px]">
                <b>{labels.right}:</b> {r.rightRange}
              </p>
            </div>
          ))}
        </Section>
      )}

      {filteredPointDiffs.length > 0 && (
        <Section title={`Point differences (${filteredPointDiffs.length})`}>
          <div className="overflow-x-auto">
            <table className="w-full text-xs border-collapse">
              <thead>
                <tr className="bg-gray-100 text-left">
                  <th className="p-1.5 border border-gray-200">Series</th>
                  <th className="p-1.5 border border-gray-200">x</th>
                  <th className="p-1.5 border border-gray-200">{labels.left}</th>
                  <th className="p-1.5 border border-gray-200">{labels.right}</th>
                  <th className="p-1.5 border border-gray-200">Δ</th>
                </tr>
              </thead>
              <tbody>
                {filteredPointDiffs.slice(0, 200).map((p, i) => (
                  <tr key={i}>
                    <td className="p-1.5 border border-gray-200">{p.series}</td>
                    <td className="p-1.5 border border-gray-200">{String(p.x)}</td>
                    <td className="p-1.5 border border-gray-200 text-red-700">{Number.isFinite(p.left) ? p.left : '—'}</td>
                    <td className="p-1.5 border border-gray-200 text-red-700">{Number.isFinite(p.right) ? p.right : '—'}</td>
                    <td className="p-1.5 border border-gray-200">{Number.isFinite(p.delta) ? p.delta : '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Section>
      )}
      {diff.overlayDiffs.length > 0 && (
        <Section title="Overlay markers">
          {diff.overlayDiffs.map((o, i) => (
            <p key={i}>x={String(o.x)}: "{o.leftLabel ?? '(none)'}" ({labels.left}) vs "{o.rightLabel ?? '(none)'}" ({labels.right})</p>
          ))}
        </Section>
      )}
    </>
  );
}

function ChartShot({ label, base64 }: { label: string; base64?: string }) {
  if (!base64) {
    return (
      <div className="border border-dashed border-gray-300 rounded p-3 text-center text-xs text-gray-400">
        {label} — no screenshot captured
      </div>
    );
  }
  return (
    <div>
      <p className="text-[11px] font-semibold text-gray-600 mb-1">{label}</p>
      <img src={`data:image/png;base64,${base64}`} alt={`${label} chart`} className="w-full rounded border border-gray-200" />
    </div>
  );
}

interface AxisRelabel {
  series: string;
  leftRange: string;
  rightRange: string;
}

/**
 * Detect series where the plotted y-values match position-by-position on
 * both sides but the x-axis labels differ. Common when migrating from
 * an old UI that uses indexes ("0..35") to a new UI that uses years
 * ("2032..2067") — the data is the same; the relabel alone shouldn't
 * produce N point-difference rows.
 *
 * Heuristic: same series length AND every y-value matches within a
 * tiny epsilon. Tolerance is hardcoded at 0 — the chart comparator
 * already applied the user's tolerance when building pointDiffs, and
 * here we just want exact matches.
 */
function detectAxisRelabels(diff: ChartDiff): AxisRelabel[] {
  if (!diff.seriesAxisInfo) return [];
  const out: AxisRelabel[] = [];
  for (const [series, info] of Object.entries(diff.seriesAxisInfo)) {
    const { leftXs, rightXs, leftYs, rightYs } = info;
    if (leftYs.length === 0 || leftYs.length !== rightYs.length) continue;
    let allMatch = true;
    for (let i = 0; i < leftYs.length; i++) {
      const ly = leftYs[i];
      const ry = rightYs[i];
      if (ly !== ry) { allMatch = false; break; }
    }
    if (!allMatch) continue;
    // Y values match in order — check that x labels differ at all (else it's a pure match).
    let xDiffers = false;
    for (let i = 0; i < leftXs.length; i++) {
      if (leftXs[i] !== rightXs[i]) { xDiffers = true; break; }
    }
    if (!xDiffers) continue;
    out.push({
      series,
      leftRange: summarizeXRange(leftXs),
      rightRange: summarizeXRange(rightXs),
    });
  }
  return out;
}

/**
 * Compact form of a long axis-label list. "2032, 2033, 2034 … 2067 (36 points)"
 * is friendlier than dumping every label inline.
 */
function summarizeXRange(xs: Array<string | number>): string {
  if (xs.length === 0) return '(empty)';
  if (xs.length <= 4) return xs.map(String).join(', ');
  return `${xs[0]}, ${xs[1]}, ${xs[2]} … ${xs[xs.length - 1]} (${xs.length} points)`;
}

function SectionDiffBody({ diff, labels }: { diff: SectionDiff; labels: { left: string; right: string } }) {
  return (
    <>
      {diff.unrenderedValues && diff.unrenderedValues.length > 0 && (
        <UnrenderedValuesSection values={diff.unrenderedValues} labels={labels} />
      )}
      {diff.titleMismatch && (
        <Section title="Title">
          <p><b>{labels.left}:</b> "{diff.titleMismatch.left}"</p>
          <p><b>{labels.right}:</b> "{diff.titleMismatch.right}"</p>
        </Section>
      )}
      {(diff.missingItemsOnLeft.length > 0 || diff.missingItemsOnRight.length > 0) && (
        <Section title="Missing items">
          {diff.missingItemsOnLeft.length > 0 && <p>Missing on <b>{labels.left}:</b> {diff.missingItemsOnLeft.join(', ')}</p>}
          {diff.missingItemsOnRight.length > 0 && <p>Missing on <b>{labels.right}:</b> {diff.missingItemsOnRight.join(', ')}</p>}
        </Section>
      )}
      {diff.itemDiffs.length > 0 && (
        <Section title={`Item value differences (${diff.itemDiffs.length})`}>
          <div className="overflow-x-auto">
            <table className="w-full text-xs border-collapse">
              <thead>
                <tr className="bg-gray-100 text-left">
                  <th className="p-1.5 border border-gray-200">Label</th>
                  <th className="p-1.5 border border-gray-200">{labels.left}</th>
                  <th className="p-1.5 border border-gray-200">{labels.right}</th>
                </tr>
              </thead>
              <tbody>
                {diff.itemDiffs.map((it, i) => (
                  <tr key={i}>
                    <td className="p-1.5 border border-gray-200">{it.label}</td>
                    <td className="p-1.5 border border-gray-200 text-red-700">{it.leftValue ?? ''}</td>
                    <td className="p-1.5 border border-gray-200 text-red-700">{it.rightValue ?? ''}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Section>
      )}
    </>
  );
}

function StyleDiffBody({ diff, labels }: { diff: StyleDiff; labels: { left: string; right: string } }) {
  return (
    <>
      {diff.unrenderedValues && diff.unrenderedValues.length > 0 && (
        <UnrenderedValuesSection values={diff.unrenderedValues} labels={labels} />
      )}
      <Section title={`Style properties (${diff.differences.length})`}>
      <div className="overflow-x-auto">
        <table className="w-full text-xs border-collapse">
          <thead>
            <tr className="bg-gray-100 text-left">
              <th className="p-1.5 border border-gray-200">Property</th>
              <th className="p-1.5 border border-gray-200">{labels.left}</th>
              <th className="p-1.5 border border-gray-200">{labels.right}</th>
            </tr>
          </thead>
          <tbody>
            {diff.differences.map((p, i) => (
              <tr key={i}>
                <td className="p-1.5 border border-gray-200 font-mono">{p.property}</td>
                <td className="p-1.5 border border-gray-200 text-red-700">{p.left}</td>
                <td className="p-1.5 border border-gray-200 text-red-700">{p.right}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      </Section>
    </>
  );
}
