import { useState } from 'react';
import classnames from 'classnames';
import type { ConsoleMessageSummary } from '../../../activator/types/state';

interface Props {
  msg: ConsoleMessageSummary;
}

const rowClassMap: Record<ConsoleMessageSummary['type'], string> = {
  error: 'border-l-red-400 hover:bg-red-50/60',
  warn: 'border-l-yellow-400 hover:bg-yellow-50/60',
  info: 'border-l-blue-400 hover:bg-blue-50/60',
  debug: 'border-l-gray-300 hover:bg-gray-50',
  log: 'border-l-gray-300 hover:bg-gray-50',
};

const badgeClassMap: Record<ConsoleMessageSummary['type'], string> = {
  error: 'bg-red-100 text-red-700',
  warn: 'bg-yellow-100 text-yellow-700',
  info: 'bg-blue-100 text-blue-700',
  debug: 'bg-gray-200 text-gray-600',
  log: 'bg-gray-200 text-gray-600',
};

const typeShortLabel: Record<ConsoleMessageSummary['type'], string> = {
  error: 'ERR',
  warn: 'WRN',
  info: 'INF',
  debug: 'DBG',
  log: 'LOG',
};

function splitMessageAndStack(text: string): { headline: string; stack: string | null } {
  const newlineIdx = text.indexOf('\n');
  if (newlineIdx < 0) return { headline: text, stack: null };
  return { headline: text.slice(0, newlineIdx), stack: text.slice(newlineIdx + 1) };
}

function shortenLocation(url: string | undefined, lineNumber: number | undefined): string {
  if (!url) return lineNumber != null ? `:${lineNumber}` : '';
  let label = url;
  try {
    const parsed = new URL(url);
    const segments = parsed.pathname.split('/').filter(Boolean);
    label = segments[segments.length - 1] || parsed.host;
  } catch {
    const parts = url.split('/');
    label = parts[parts.length - 1] || url;
  }
  if (label.length > 36) label = `…${label.slice(-35)}`;
  return lineNumber != null ? `${label}:${lineNumber}` : label;
}

export default function ConsoleMessageCard({ msg }: Props) {
  const [expanded, setExpanded] = useState(false);
  const { headline, stack } = splitMessageAndStack(msg.text ?? '');
  const location = shortenLocation(msg.url, msg.lineNumber);
  const fullLocation = msg.url ? `${msg.url}${msg.lineNumber != null ? `:${msg.lineNumber}` : ''}` : '';
  const hasMore = !!stack || headline.length > 200 || (!!fullLocation && fullLocation !== location);

  return (
    <div
      className={classnames(
        'border-l-2 bg-white rounded-r-md transition-colors',
        rowClassMap[msg.type],
        hasMore ? 'cursor-pointer' : '',
      )}
      onClick={hasMore ? () => setExpanded((v) => !v) : undefined}
    >
      <div className="flex items-start gap-2 px-2 py-1.5">
        <span
          className={classnames(
            'shrink-0 mt-px px-1 py-0 rounded text-[9px] font-bold tracking-wider',
            badgeClassMap[msg.type],
          )}
          title={msg.type}
        >
          {typeShortLabel[msg.type]}
        </span>

        <div className="flex-1 min-w-0">
          <div className="flex items-baseline gap-2 min-w-0">
            <p
              className={classnames(
                'text-[12px] text-gray-800 font-mono leading-snug min-w-0 flex-1',
                expanded ? 'whitespace-pre-wrap break-all' : 'truncate',
              )}
              title={!expanded ? headline : undefined}
            >
              {headline || <span className="text-gray-400">(empty)</span>}
            </p>
            {location && (
              <span
                className="shrink-0 text-[10px] text-gray-400 font-mono truncate max-w-[40%]"
                title={fullLocation}
              >
                {location}
              </span>
            )}
            {hasMore && (
              <svg
                className={classnames('w-3 h-3 text-gray-400 shrink-0 transition-transform', expanded ? 'rotate-90' : '')}
                fill="currentColor"
                viewBox="0 0 20 20"
              >
                <path
                  fillRule="evenodd"
                  d="M7.21 5.23a.75.75 0 011.06-.02l3.85 4.25a.75.75 0 010 1.02l-3.85 4.25a.75.75 0 11-1.08-1.04l3.35-3.71-3.35-3.71a.75.75 0 01.02-1.06z"
                  clipRule="evenodd"
                />
              </svg>
            )}
          </div>

          {expanded && stack && (
            <pre className="mt-1.5 text-[10.5px] font-mono text-gray-600 bg-gray-50 border border-gray-200 rounded p-2 max-h-64 overflow-auto whitespace-pre">
              {stack}
            </pre>
          )}

          {expanded && fullLocation && fullLocation !== location && (
            <p className="mt-1 text-[10px] text-gray-500 font-mono break-all">
              <span className="text-gray-400 uppercase tracking-wide mr-1">at</span>
              {fullLocation}
            </p>
          )}
        </div>
      </div>
    </div>
  );
}
