/**
 * Build URLs for the activator REST API. The UI always uses relative
 * paths so the same build works in dev and production:
 *   - Dev: vite proxies `/api/runs/*` directly to the activator (see
 *     vite.config.ts).
 *   - Prod: the backend serves the static UI and reverse-proxies
 *     `/api/runs/*` to the activator.
 */

export function executionStepScreenshotUrl(
  runId: string,
  testCaseId: string,
  stepId: string,
  variant: 'before' | 'after' = 'after',
): string {
  const qs = variant === 'before' ? '?variant=before' : '';
  return `/api/runs/executions/${encodeURIComponent(runId)}/${encodeURIComponent(testCaseId)}/${encodeURIComponent(stepId)}/screenshot.png${qs}`;
}

export function comparisonStepScreenshotUrl(
  runId: string,
  stateId: string,
  testCaseId: string,
  stepId: string,
): string {
  return `/api/runs/comparisons/${encodeURIComponent(runId)}/${encodeURIComponent(stateId)}/${encodeURIComponent(testCaseId)}/${encodeURIComponent(stepId)}/screenshot.png`;
}
