const PNG_MAGIC = 'iVBORw0KGgo';
const JPEG_MAGIC = '/9j/';
const GIF_MAGIC_1 = 'R0lGODdh';
const GIF_MAGIC_2 = 'R0lGODlh';
const WEBP_MAGIC = 'UklGR';
const BMP_MAGIC = 'Qk0';

const MIN_BASE64_IMAGE_LENGTH = 100;

export interface DetectedImage {
  src: string;
  mime: string;
}

export function detectImageInValue(value: unknown): DetectedImage | null {
  if (value == null) return null;

  if (typeof value === 'string') {
    return detectImageInString(value);
  }

  if (typeof value === 'object') {
    const obj = value as Record<string, unknown>;
    const candidate = obj.base64 ?? obj.image ?? obj.imageBase64 ?? obj.screenshot;
    if (typeof candidate === 'string') {
      const detected = detectImageInString(candidate);
      if (detected) return detected;
    }
  }

  return null;
}

function detectImageInString(s: string): DetectedImage | null {
  if (s.length < MIN_BASE64_IMAGE_LENGTH) return null;

  if (s.startsWith('data:image/')) {
    const semi = s.indexOf(';', 11);
    if (semi === -1) return null;
    const mime = s.substring(5, semi);
    return { src: s, mime };
  }

  const head = s.substring(0, 16);
  const mime = magicToMime(head);
  if (!mime) return null;

  return { src: `data:${mime};base64,${s}`, mime };
}

function magicToMime(head: string): string | null {
  if (head.startsWith(PNG_MAGIC)) return 'image/png';
  if (head.startsWith(JPEG_MAGIC)) return 'image/jpeg';
  if (head.startsWith(GIF_MAGIC_1) || head.startsWith(GIF_MAGIC_2)) return 'image/gif';
  if (head.startsWith(WEBP_MAGIC)) return 'image/webp';
  if (head.startsWith(BMP_MAGIC)) return 'image/bmp';
  return null;
}

export function stripImageFieldsForJson(value: unknown): unknown {
  if (value == null || typeof value !== 'object') return value;

  if (Array.isArray(value)) {
    return value.map(stripImageFieldsForJson);
  }

  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    if (typeof v === 'string' && detectImageInString(v)) {
      out[k] = `[image — rendered above, ${v.length} chars]`;
      continue;
    }
    out[k] = stripImageFieldsForJson(v);
  }
  return out;
}
