/**
 * Static catalog of MCP tool names, grouped for the manual-mode action selector.
 * Mirrors `activator/tools/schemas/*.ts`. Kept hand-rolled (rather than imported)
 * so the UI bundle doesn't pull in the activator tool runtime. When a new tool
 * ships in the activator schemas, add its entry here — the manual authoring UI
 * is the only consumer.
 *
 * `name` is the internal MCP function id (never shown to end users).
 * `title` is the short, human-readable label shown in the authoring UI.
 * `hint` is an optional longer one-liner shown as secondary text.
 */
export interface ManualActionCategory {
  key: string;
  label: string;
  actions: ManualAction[];
}

export interface ManualAction {
  name: string;
  title: string;
  hint?: string;
}

