/** Flat list (for quick lookup) of every action in the catalog. */
export const ALL_MANUAL_ACTIONS: ManualAction[] = MANUAL_ACTION_CATALOG.flatMap(
  (c) => c.actions,
);

const ACTION_BY_NAME: Record<string, ManualAction> = ALL_MANUAL_ACTIONS.reduce(
  (acc, a) => {
    acc[a.name] = a;
    return acc;
  },
  {} as Record<string, ManualAction>,
);

/** Find the category label for an action name, or undefined. */
export function categoryForAction(name: string): string | undefined {
  for (const cat of MANUAL_ACTION_CATALOG) {
    if (cat.actions.some((a) => a.name === name)) return cat.label;
  }
  return undefined;
}

/**
 * Human-readable short label for a tool name. Falls back to a prettified
 * form of the raw id when the tool isn't in the catalog (custom tools).
 */
export function toolTitle(name: string): string {
  if (!name) return '';
  const found = ACTION_BY_NAME[name];
  if (found) return found.title;
  const stripped = name.replace(/^browser_/, '').replace(/_/g, ' ');
  return stripped.charAt(0).toUpperCase() + stripped.slice(1);
}

/**
 * Longer descriptive line for a tool name. Returns the hint when present,
 * otherwise the title.
 */
export function toolDescription(name: string): string {
  const found = ACTION_BY_NAME[name];
  if (found) return found.hint ?? found.title;
  return toolTitle(name);
}
